package app

import (
	"context"
	"errors"
	"fmt"
	"sync"
	"time"

	"github.com/Antonio7098/ultraplan-go/internal/runcontrol"
	"github.com/Antonio7098/ultraplan-go/internal/sprint"
)

type durableOperationManager struct {
	repository runcontrol.Repository
	owner      runcontrol.Owner
	mu         sync.Mutex
	owned      map[string]*ownedDurableOperation
}

type ownedDurableOperation struct {
	fence        runcontrol.Fence
	cancel       context.CancelFunc
	stop         chan struct{}
	done         chan struct{}
	eventMu      sync.Mutex
	progressKey  string
	progressAt   time.Time
	omitted      uint64
	omittedFirst time.Time
	omittedLast  time.Time
}

// durableCLICommand is the synchronous CLI counterpart to the web/TUI
// acceptance boundary. It keeps the manager alive for the whole command and
// gives product code the cancellation-aware context owned by the durable run.
type durableCLICommand struct {
	manager  *durableOperationManager
	accepted AcceptedOperation
}

type durableOperationContextKey struct{}

type durableOperationOwnership struct {
	repository runcontrol.Repository
	fence      runcontrol.Fence
}

func beginDurableCLICommand(deps dependencies, request OperationRequest) (*durableCLICommand, error) {
	repository, _, err := runRepository(deps)
	if err != nil {
		return nil, err
	}
	manager := newDurableOperationManager(repository, deps.runControl.owner)
	accepted, err := manager.AcceptOperation(deps.ctx, Confirmation{Request: request}, "")
	if err != nil {
		return nil, classifiedCause(ExitRuntime, err, "run-control.accept")
	}
	return &durableCLICommand{manager: manager, accepted: accepted}, nil
}

func (c *durableCLICommand) Context() context.Context { return c.accepted.Context }

func (c *durableCLICommand) QAWriterToken() (sprint.QAWriterToken, func(sprint.QAWriterToken) error, error) {
	if c == nil {
		return sprint.QAWriterToken{}, nil, errors.New("durable QA ownership is unavailable")
	}
	return qaOwnershipFromContext(c.accepted.Context)
}

func (c *durableCLICommand) Finish(runErr error) error {
	state := OperationComplete
	if c.accepted.Context.Err() != nil {
		state = OperationCancelled
	} else if runErr != nil {
		state = OperationFailed
	}
	ctx, cancel := context.WithTimeout(context.Background(), 30*time.Second)
	defer cancel()
	if err := c.manager.FinishOperation(ctx, c.accepted.RunID, state, runErr); err != nil {
		return classifiedCause(ExitRuntime, err, "run-control.finish")
	}
	return nil
}

func finishDurableCLICommand(command *durableCLICommand, runErr error) error {
	if command == nil {
		return runErr
	}
	return errors.Join(runErr, command.Finish(runErr))
}

func newDurableOperationManager(repository runcontrol.Repository, owner runcontrol.Owner) *durableOperationManager {
	return &durableOperationManager{repository: repository, owner: owner, owned: make(map[string]*ownedDurableOperation)}
}

func (m *durableOperationManager) AcceptOperation(ctx context.Context, confirmation Confirmation, digest string) (AcceptedOperation, error) {
	req := confirmation.Request
	target := runcontrol.Target{
		Kind: "operation", Operation: string(req.Kind), Project: req.Project, Sprint: req.Sprint,
		Study: req.Study, Stage: req.Stage, Task: req.Task,
	}
	snapshot, err := m.repository.Accept(ctx, runcontrol.Acceptance{
		Target: target, ProductStatus: "prepared", OperationAlias: digest, ConfirmationDigest: digest,
	})
	if err != nil && digest != "" && errors.Is(err, runcontrol.ErrConflict) {
		existing, resolveErr := m.repository.ResolveOperationAlias(ctx, digest)
		if resolveErr != nil {
			return AcceptedOperation{}, errors.Join(err, resolveErr)
		}
		return AcceptedOperation{RunID: string(existing.RunID), Context: ctx, Existing: true, Lifecycle: string(existing.Lifecycle)}, nil
	}
	if err != nil {
		return AcceptedOperation{}, fmt.Errorf("persist confirmed operation acceptance: %w", err)
	}
	attempt, _, err := m.repository.Claim(ctx, runcontrol.Claim{RunID: snapshot.RunID, Owner: m.owner, Lease: runcontrol.OwnerLeaseDuration})
	if err != nil {
		return AcceptedOperation{}, fmt.Errorf("persist confirmed operation owner claim: %w", err)
	}
	fence := runcontrol.Fence{RunID: snapshot.RunID, AttemptID: attempt.ID, OwnerID: m.owner.ID, FencingGeneration: attempt.FencingGeneration}
	if _, _, err := appendRunEventWithRetry(ctx, m.repository, fence, runcontrol.EventDraft{
		Type: runcontrol.EventLifecycle, Lifecycle: runcontrol.LifecycleRunning,
		Payload: map[string]string{"lifecycle": string(runcontrol.LifecycleRunning)},
	}); err != nil {
		terminalCtx, cancel := context.WithTimeout(context.Background(), 30*time.Second)
		_, _, _ = proposeRunTerminalWithRetry(terminalCtx, m.repository, fence, runcontrol.TerminalProposal{Outcome: runcontrol.TerminalPersistenceLost, Reason: "operation start persistence failed", ProposedBy: m.owner.ID})
		cancel()
		return AcceptedOperation{}, fmt.Errorf("persist confirmed operation start: %w", err)
	}
	operationCtx, cancel := context.WithCancel(runcontrol.WithParentRun(ctx, snapshot.RunID))
	operationCtx = context.WithValue(operationCtx, durableOperationContextKey{}, durableOperationOwnership{repository: m.repository, fence: fence})
	owned := &ownedDurableOperation{fence: fence, cancel: cancel, stop: make(chan struct{}), done: make(chan struct{})}
	m.mu.Lock()
	m.owned[string(snapshot.RunID)] = owned
	m.mu.Unlock()
	go m.controlOperation(operationCtx, owned)
	return AcceptedOperation{RunID: string(snapshot.RunID), Context: operationCtx, Lifecycle: string(runcontrol.LifecycleRunning)}, nil
}

func qaOwnershipFromContext(ctx context.Context) (sprint.QAWriterToken, func(sprint.QAWriterToken) error, error) {
	ownership, ok := ctx.Value(durableOperationContextKey{}).(durableOperationOwnership)
	if !ok || ownership.repository == nil {
		return sprint.QAWriterToken{}, nil, errors.New("durable QA ownership is missing from the operation context")
	}
	token := sprint.QAWriterToken{RunID: string(ownership.fence.RunID), OperationalAttemptID: string(ownership.fence.AttemptID), FencingGeneration: ownership.fence.FencingGeneration}
	fence := func(got sprint.QAWriterToken) error {
		if got != token {
			return runcontrol.ErrStaleFence
		}
		fenceCtx, cancel := context.WithTimeout(context.WithoutCancel(ctx), 30*time.Second)
		defer cancel()
		_, err := ownership.repository.Heartbeat(fenceCtx, ownership.fence, runControlLease)
		return err
	}
	return token, fence, nil
}

func (m *durableOperationManager) RecordOperationEvent(ctx context.Context, runID string, event OperationEvent) (bool, error) {
	m.mu.Lock()
	owned := m.owned[runID]
	m.mu.Unlock()
	if owned == nil {
		return false, runcontrol.ErrNotFound
	}
	owned.eventMu.Lock()
	defer owned.eventMu.Unlock()
	eventType := runcontrol.EventProgress
	if event.State == OperationFailed {
		eventType = runcontrol.EventWarning
	}
	key := string(eventType) + "\x00" + event.Stage + "\x00" + event.Task + "\x00" + event.PhaseState + "\x00" + event.SafeSummary + "\x00" + event.EventType + "\x00" + event.EventKind + "\x00" + event.Tool + "\x00" + event.Reason + "\x00" + event.Detail
	now := time.Now().UTC()
	elapsed := now.Sub(owned.progressAt)
	if eventType == runcontrol.EventProgress && key == owned.progressKey && elapsed >= 0 && elapsed < runcontrol.ProgressCoalesceWindow {
		if owned.omitted == 0 {
			owned.omittedFirst = now
		}
		owned.omitted++
		owned.omittedLast = now
		return false, nil
	}
	payload := map[string]string{
		"state": string(event.State), "type": event.EventType,
		"count": fmt.Sprintf("%d/%d", event.Completed, event.Total),
	}
	for key, value := range map[string]string{
		"phase_state": event.PhaseState, "summary": event.SafeSummary,
		"tool_call_id": event.ToolCallID, "tool_status": event.ToolStatus,
		"tool_arguments": event.ToolArguments, "tool_result": event.ToolResult, "tool_error": event.ToolError,
		"provider": event.Provider, "model": event.Model, "harness": event.Harness,
	} {
		if value != "" {
			payload[key] = value
		}
	}
	var omission *runcontrol.Omission
	if event.Message != "" {
		omission = &runcontrol.Omission{Reason: "presentation message omitted", Count: 1}
	}
	if owned.omitted > 0 {
		if omission == nil {
			omission = &runcontrol.Omission{Reason: "equivalent progress coalesced"}
		}
		omission.Count += owned.omitted
		omission.FirstAt, omission.LastAt = &owned.omittedFirst, &owned.omittedLast
		owned.omitted = 0
	}
	_, _, err := appendRunEventWithRetry(ctx, m.repository, owned.fence, runcontrol.EventDraft{
		Type: eventType, Scope: runcontrol.EventScopeOperation, Stage: event.Stage, Task: event.Task,
		Kind: event.EventKind, Tool: event.Tool, Action: event.Action, Reason: event.Reason,
		Detail: event.Detail, Payload: payload, Omission: omission,
	})
	if err != nil {
		owned.cancel()
		return false, err
	}
	if eventType == runcontrol.EventProgress {
		owned.progressKey, owned.progressAt = key, now
	}
	return true, nil
}

func (m *durableOperationManager) controlOperation(ctx context.Context, owned *ownedDurableOperation) {
	defer close(owned.done)
	ticker := time.NewTicker(runcontrol.OwnerTickInterval)
	defer ticker.Stop()
	lastHeartbeat, lastReconcile := time.Now(), time.Now()
	for {
		select {
		case <-ctx.Done():
			return
		case <-owned.stop:
			return
		case now := <-ticker.C:
			snapshot, err := m.repository.Snapshot(ctx, owned.fence.RunID)
			if err != nil {
				owned.cancel()
				return
			}
			if snapshot.Cancellation.State == runcontrol.CancellationRequested {
				if _, _, err := m.repository.AcknowledgeCancellation(ctx, owned.fence); err != nil {
					owned.cancel()
					return
				}
				owned.cancel()
				return
			}
			if now.Sub(lastHeartbeat) >= runcontrol.HeartbeatInterval {
				if _, err := m.repository.Heartbeat(ctx, owned.fence, runcontrol.OwnerLeaseDuration); err != nil {
					owned.cancel()
					return
				}
				lastHeartbeat = now
			}
			if now.Sub(lastReconcile) >= runcontrol.ReconciliationInterval {
				if _, err := m.repository.Reconcile(ctx, runcontrol.NativeProcessProbe{}, runcontrol.ReconcileOptions{}); err != nil {
					owned.cancel()
					return
				}
				lastReconcile = now
			}
		}
	}
}

func (m *durableOperationManager) FinishOperation(ctx context.Context, runID string, state OperationState, runErr error) error {
	m.mu.Lock()
	owned := m.owned[runID]
	delete(m.owned, runID)
	m.mu.Unlock()
	if owned == nil {
		return nil
	}
	owned.eventMu.Lock()
	if owned.omitted > 0 {
		_, _, appendErr := appendRunEventWithRetry(ctx, m.repository, owned.fence, runcontrol.EventDraft{Type: runcontrol.EventOmission, Omission: &runcontrol.Omission{Reason: "equivalent progress coalesced", Count: owned.omitted, FirstAt: &owned.omittedFirst, LastAt: &owned.omittedLast}})
		if appendErr != nil && runErr == nil {
			runErr = appendErr
		}
		owned.omitted = 0
	}
	owned.eventMu.Unlock()
	close(owned.stop)
	<-owned.done
	owned.cancel()
	outcome := runcontrol.TerminalSucceeded
	reason := "operation completed"
	switch {
	case errors.Is(runErr, context.DeadlineExceeded):
		outcome, reason = runcontrol.TerminalTimedOut, "operation deadline exceeded"
	case errors.Is(runErr, context.Canceled), state == OperationCancelled:
		outcome, reason = runcontrol.TerminalCancelled, "operation cancelled"
	case runErr != nil, state == OperationFailed:
		outcome, reason = runcontrol.TerminalFailed, "operation failed"
	case state == OperationPartial:
		outcome, reason = runcontrol.TerminalInterrupted, "operation interrupted"
	}
	_, _, err := proposeRunTerminalWithRetry(ctx, m.repository, owned.fence, runcontrol.TerminalProposal{Outcome: outcome, Reason: reason, ProposedBy: m.owner.ID})
	return err
}

package app

import (
	"context"
	"crypto/sha256"
	"encoding/hex"
	"encoding/json"
	"errors"
	"fmt"
	"io/fs"
	"os"
	"path/filepath"
	"sort"
	"strings"
	"time"

	runtimepkg "github.com/Antonio7098/ultraplan-go/internal/platform/runtime"
	"github.com/Antonio7098/ultraplan-go/internal/project"
	"github.com/Antonio7098/ultraplan-go/internal/sprint"
	"github.com/Antonio7098/ultraplan-go/internal/study"
)

// OperationalUseCases is the terminal-adapter boundary for interactive actions.
// Its values deliberately contain no CLI, runtime-provider, or TUI framework types.
type OperationalUseCases interface {
	ReadOnlyUseCases
	WebOperations
}

// WebOperations is the closed operation capability available to transport
// adapters. It deliberately excludes surface-specific dashboard result types.
type WebOperations interface {
	Validate(context.Context, ValidationRequest) (ValidationOperationResult, error)
	PrepareOperation(context.Context, OperationRequest) (Confirmation, error)
	RunOperation(context.Context, OperationRequest, func(OperationEvent)) (OperationResult, error)
}

// DurableOperationManager is an optional capability used by interactive
// adapters to persist acceptance and the first owner claim before they create
// an execution goroutine. The confirmation digest is already non-reversible.
type DurableOperationManager interface {
	AcceptOperation(context.Context, Confirmation, string) (AcceptedOperation, error)
	RecordOperationEvent(context.Context, string, OperationEvent) (bool, error)
	FinishOperation(context.Context, string, OperationState, error) error
}

type AcceptedOperation struct {
	RunID     string
	Context   context.Context
	Existing  bool
	Lifecycle string
}

// OperationCleanupRecorder is an optional durability capability used by a
// server that can no longer prove cleanup before its shutdown deadline.
// Transport adapters supply identity and reason; product modules own storage.
type OperationCleanupRecorder interface {
	RecordOperationCleanupUncertain(context.Context, OperationCleanupUncertain) error
}

type OperationCleanupUncertain struct {
	OperationID string
	Request     OperationRequest
	Reason      string
	RecordedAt  time.Time
}

type OperationReconciler interface {
	ReconcileOperations(context.Context) error
}

type OperationKind string

const (
	OperationValidate      OperationKind = "validate"
	OperationSprintStatus  OperationKind = "sprint-status"
	OperationPrompt        OperationKind = "sprint-prompt"
	OperationFlowDryRun    OperationKind = "sprint-flow-dry-run"
	OperationFlow          OperationKind = "sprint-flow"
	OperationStageDryRun   OperationKind = "sprint-stage-dry-run"
	OperationStage         OperationKind = "sprint-stage"
	OperationExecuteStatus OperationKind = "execute-status"
	OperationExecuteDryRun OperationKind = "execute-dry-run"
	OperationExecuteStart  OperationKind = "execute-start"
	OperationExecuteResume OperationKind = "execute-resume"
	OperationReviewStatus  OperationKind = "review-status"
	OperationReviewDryRun  OperationKind = "review-dry-run"
	OperationReviewStart   OperationKind = "review-start"
	OperationSmokeStatus   OperationKind = "smoke-status"
	OperationSmokeDryRun   OperationKind = "smoke-dry-run"
	OperationSmokeStart    OperationKind = "smoke-start"
	OperationVerifyDryRun  OperationKind = "verify-dry-run"
	OperationVerifyStart   OperationKind = "verify-start"
	OperationQAStatus      OperationKind = "qa-status"
	OperationQADryRun      OperationKind = "qa-dry-run"
	OperationQAStart       OperationKind = "qa-start"
	OperationQAResume      OperationKind = "qa-resume"
	OperationQARecover     OperationKind = "qa-recover"
	OperationStudyStart    OperationKind = "study-start"
	OperationStudyResume   OperationKind = "study-resume"
	OperationStudyCancel   OperationKind = "study-cancel"
)

type OperationState string

const (
	OperationPreparing OperationState = "preparing"
	OperationRunning   OperationState = "running"
	OperationComplete  OperationState = "complete"
	OperationFailed    OperationState = "failed"
	OperationCancelled OperationState = "cancelled"
	OperationPartial   OperationState = "partial"
)

type OperationRequest struct {
	Kind                                OperationKind
	Project, Sprint, Study, Stage, Task string
	// Model optionally overrides the runtime model (provider/model) for this
	// operation. Empty keeps the workspace-configured default unchanged.
	Model               string
	Level, Suite, Test  string
	Timeout             string
	ForceReview         bool
	RestartReview       bool
	OverrideRationale   string
	ReviewFocus         []string
	Sources, Dimensions []string
	Parallelism         int
	// ExpectedFingerprint is server-issued authority. Transport decoders must
	// never accept it from a caller; it is populated by PrepareOperation and
	// checked again immediately before execution.
	ExpectedFingerprint string
}
type Confirmation struct {
	Request                          OperationRequest
	Subject                          string
	Paths, Scope                     []string
	Runtime, Mutates                 bool
	Warning, ModelSource, Permission string
	MutationClass                    string
	Prerequisites                    []string
	GovernedInputs                   []string
	CanonicalRequest                 string
	InputFingerprint                 string
	DurableRefreshPath               string
}
type OperationEvent struct {
	State                                                                         OperationState
	Stage, Task, Message, PhaseState, SafeSummary                                 string
	EventKind, EventType, Tool, Action, Reason, Detail                            string
	ToolCallID, ToolStatus, ToolArguments, ToolResult, ToolError                  string
	Completed, Total, Attempt                                                     int
	RuntimeAttempts                                                               int
	Turns                                                                         int64
	TurnsKnown                                                                    bool
	Tokens                                                                        int64
	TokensKnown                                                                   bool
	InputTokens, OutputTokens, ReasoningTokens, CacheReadTokens, CacheWriteTokens int64
	Duration, Provider, Model, Harness, Cost                                      string
	RuntimeEvents                                                                 int64
}

func applyRuntimeObservation(target *OperationEvent, event runtimepkg.Event) {
	target.EventType = event.Type
	target.EventKind = event.Kind
	target.Tool = runtimeEventValue(event, "tool", "name")
	target.Action = runtimeEventValue(event, "action", "state", "phase", "status")
	target.Reason = runtimeEventValue(event, "reason")
	target.Detail = runtimeEventValue(event, "detail", "error", "message")
	if event.Kind == "tool" {
		normalized := map[string]string{}
		captureToolObservation(normalized, event.Payload)
		if target.Tool == "" {
			target.Tool = normalized["tool_name"]
		}
		if target.Action == "" {
			target.Action = normalized["tool_status"]
		}
		target.ToolCallID = normalized["tool_call_id"]
		target.ToolStatus = normalized["tool_status"]
		target.ToolArguments = normalized["tool_arguments"]
		target.ToolResult = normalized["tool_result"]
		target.ToolError = normalized["tool_error"]
	}
	if target.Provider == "" {
		target.Provider = runtimeEventValue(event, "provider")
	}
	if target.Model == "" {
		target.Model = runtimeEventValue(event, "model")
	}
	if target.Harness == "" {
		target.Harness = runtimeEventValue(event, "harness", "runtime_kind")
	}
}

type OperationResult struct {
	State                     OperationState
	RunID                     string
	Subject, Message, Content string
	Truncated                 bool
	Findings                  []DisplayFinding
	Error                     *OperationError
}
type OperationError struct {
	Code, Category, Operation, Component, Message, Cause, Guidance string
	Retryable                                                      bool
}

var ErrStaleOperation = errors.New("operation inputs changed after preparation")

func (u dashboardUseCases) PrepareOperation(ctx context.Context, req OperationRequest) (Confirmation, error) {
	if err := ctx.Err(); err != nil {
		return Confirmation{}, err
	}
	req.ExpectedFingerprint = ""
	req = normalizeOperationRequest(req)
	if err := validateOperationScope(req); err != nil {
		return Confirmation{}, err
	}
	if err := validateQAOperationRequest(req); err != nil {
		return Confirmation{}, err
	}
	if (req.Kind == OperationReviewStart || req.Kind == OperationReviewDryRun) && req.Parallelism <= 0 {
		req.Parallelism = u.reviewConcurrency
	}
	c := Confirmation{Request: req, Subject: operationFirstNonEmpty(req.Project+"/"+req.Sprint, req.Study), Permission: "workspace policy enforced"}
	switch req.Kind {
	case OperationValidate, OperationPrompt, OperationFlowDryRun, OperationStageDryRun, OperationExecuteDryRun, OperationExecuteStatus, OperationReviewDryRun, OperationReviewStatus, OperationSmokeStatus, OperationQAStatus:
		c.Scope = []string{req.Stage}
		c.Warning = "runtime-free; no runtime-backed writes"
	case OperationQADryRun:
		if req.Suite == "smoke" {
			smoke, err := u.sprintService().RunSmoke(ctx, req.Project, req.Sprint, sprint.SmokeRequest{DryRun: true})
			if err != nil {
				return c, err
			}
			c.Scope = []string{"canonical containing smoke selection", smoke.ScopeKind + " " + smoke.Scope}
			c.Warning = "RUNTIME-FREE SMOKE PREFLIGHT; NO HARNESS INVOCATION"
			break
		}
		mapped, err := u.QAMap(ctx, QARequest{Project: req.Project, Sprint: req.Sprint})
		if err != nil {
			return c, err
		}
		c.Scope = []string{fmt.Sprintf("deterministic map %s", mapped.MapFingerprint), fmt.Sprintf("%d changed paths in %d bounded shards", mapped.ChangedPaths, mapped.TotalShards)}
		c.Warning = "RUNTIME-FREE; TARGET AND GOVERNED INPUTS READ-ONLY; NO QA STATE WRITE"
	case OperationQAStart, OperationQAResume:
		if req.Suite == "smoke" {
			c.Runtime, c.Mutates = true, true
			c.Scope = []string{"one canonical smoke harness invocation", "one smoke.md and flow-state update"}
			c.Warning = "RUNTIME + EXTERNAL HARNESS EVIDENCE; IMPLEMENTATION TARGET READ-ONLY"
			break
		}
		mapped, err := u.QAMap(ctx, QARequest{Project: req.Project, Sprint: req.Sprint})
		if err != nil {
			return c, err
		}
		if req.Task != "" {
			owned := false
			for _, shard := range mapped.Shards {
				owned = owned || shard.ID == req.Task
			}
			if !owned {
				return c, fmt.Errorf("selected QA shard is not owned by the current map")
			}
		}
		c.Runtime, c.Mutates = true, true
		c.Scope = []string{fmt.Sprintf("deterministic map %s", mapped.MapFingerprint), fmt.Sprintf("bounded concurrency and %d total shards", mapped.TotalShards)}
		if req.Task != "" {
			c.Scope = append(c.Scope, "map-owned shard "+req.Task)
		}
		c.Warning = "RUNTIME + PRIVATE QA STATE WRITE; IMPLEMENTATION TARGET READ-ONLY"
	case OperationQARecover:
		c.Mutates = true
		c.Scope = []string{"QA pointer, digest, interrupted ownership, flow summary, and retention reconciliation"}
		c.Warning = "RUNTIME-FREE QA RECOVERY; NO CHILD WORK"
	case OperationSprintStatus:
		c.Mutates = true
		c.Scope = []string{"all sprint stages", "execute and Conformance Review state"}
		c.Warning = "RUNTIME-FREE; MAY REFRESH FLOW-STATE.JSON"
	case OperationFlow:
		c.Runtime = true
		c.Mutates = true
		c.Scope = []string{"planning stages through " + req.Stage}
		c.Warning = "RUNTIME + WORKSPACE MUTATION"
	case OperationStage:
		c.Runtime = true
		c.Mutates = true
		c.Scope = []string{"selected planning stage only: " + req.Stage}
		c.Warning = "RUNTIME + WORKSPACE MUTATION; PREREQUISITES MUST ALREADY BE VALID"
	case OperationExecuteStart, OperationExecuteResume:
		c.Runtime = true
		c.Mutates = true
		c.Scope = []string{"execute tasks"}
		c.Warning = "RUNTIME + APPROVED TARGET MUTATION"
	case OperationReviewStart:
		c.Runtime = true
		c.Mutates = true
		c.Scope = []string{"one read-only Conformance Review worker per selected contract plus handbook", fmt.Sprintf("bounded parallelism: %d", req.Parallelism)}
		if req.RestartReview {
			c.Scope = append(c.Scope, "discard resumable Conformance Review checkpoints and start fresh sessions")
		}
		c.Warning = "RUNTIME + REVIEW ARTIFACT WRITE (TARGET READ-ONLY)"
	case OperationSmokeDryRun, OperationSmokeStart:
		preview, err := u.sprintService().RunSmoke(ctx, req.Project, req.Sprint, sprint.SmokeRequest{Level: req.Level, Suite: req.Suite, Test: req.Test, ForceReview: req.ForceReview, OverrideConfirmed: req.ForceReview, OverrideRationale: req.OverrideRationale, DryRun: true})
		if err != nil {
			return c, err
		}
		c.Runtime = true
		c.Mutates = req.Kind == OperationSmokeStart
		c.Scope = []string{fmt.Sprintf("%s %s", preview.ScopeKind, preview.Scope), preview.ScopeRationale, "prerequisites: " + strings.Join(preview.Prerequisites, ", "), "duration/cost: " + preview.DurationClass + "/" + preview.CostClass, fmt.Sprintf("timeout: %s (source: %s)", preview.EffectiveTimeout, preview.TimeoutSource), "safe command: " + preview.SafeArgv, "evidence roots: " + strings.Join(preview.EvidenceRoots, ", ")}
		c.Warning = "EXTERNAL HARNESS + SMOKE ARTIFACT WRITE; RAW EVIDENCE REMAINS EXTERNAL"
	case OperationVerifyDryRun, OperationVerifyStart:
		c.Runtime, c.Mutates = true, req.Kind == OperationVerifyStart
		c.Scope = []string{"complete execute evidence", "current Conformance Review", "Conformance Review-gated containing smoke scope"}
		if req.ForceReview {
			c.Scope = append(c.Scope, "DIAGNOSTIC OVERRIDE: "+req.OverrideRationale)
		}
		c.Warning = "ORDERED REVIEW -> SMOKE VERIFICATION; CANONICAL EVIDENCE ONLY AFTER VALIDATION"
	case OperationStudyStart, OperationStudyResume:
		if req.Parallelism < 1 || req.Parallelism > 64 {
			return c, fmt.Errorf("parallelism must be between 1 and 64")
		}
		c.Runtime = true
		c.Mutates = true
		c.Scope = []string{fmt.Sprintf("study run-loop with %d parallel workers", req.Parallelism)}
		c.Warning = "RUNTIME + STUDY STATE MUTATION"
	case OperationStudyCancel:
		c.Mutates = true
		c.Scope = []string{"active study run-loop"}
		c.Warning = "CANCEL ACTIVE RUN LOOP"
	default:
		return c, fmt.Errorf("unsupported operation %q", req.Kind)
	}
	if req.Project != "" {
		if req.Sprint != "" {
			c.Paths = []string{"projects/" + req.Project + "/sprints/" + req.Sprint}
			c.DurableRefreshPath = "/api/v1/projects/" + req.Project + "/sprints/" + req.Sprint
		} else {
			c.Paths = []string{"projects/" + req.Project}
			c.DurableRefreshPath = "/api/v1/projects/" + req.Project
		}
	} else {
		c.Paths = []string{"studies/" + req.Study}
		c.DurableRefreshPath = "/api/v1/studies/" + req.Study
	}
	if c.Mutates {
		if req.Project != "" {
			c.MutationClass = "sprint_mutation"
		} else {
			c.MutationClass = "study_mutation"
		}
	} else {
		c.MutationClass = "read_only"
	}
	if c.Runtime {
		c.ModelSource = operationRuntimeIdentity(req, u.stageRuntime)
	}
	c.Prerequisites = operationPrerequisites(req)
	canonical, err := canonicalOperationRequest(req)
	if err != nil {
		return c, err
	}
	c.CanonicalRequest = canonical
	c.GovernedInputs = governedOperationInputs(req)
	fingerprintBasis := canonical + "\nruntime=" + c.ModelSource + "\nscope=" + strings.Join(c.Scope, "\x00")
	fingerprint, err := fingerprintOperationInputs(u.root, fingerprintBasis, c.GovernedInputs)
	if err != nil {
		return c, err
	}
	c.InputFingerprint = fingerprint
	c.Request.ExpectedFingerprint = fingerprint
	return c, nil
}

func validateQAOperationRequest(req OperationRequest) error {
	switch req.Kind {
	case OperationQAStatus, OperationQADryRun, OperationQAStart, OperationQAResume, OperationQARecover:
	default:
		return nil
	}
	if req.Study != "" || req.Stage != "" || req.Model != "" || req.Level != "" || req.Test != "" || req.Timeout != "" || req.ForceReview || req.RestartReview || req.OverrideRationale != "" || len(req.ReviewFocus) > 0 || len(req.Sources) > 0 || len(req.Dimensions) > 0 || req.Parallelism != 0 {
		return fmt.Errorf("QA operations accept only project, sprint, and a map-owned shard")
	}
	if req.Suite != "" && req.Suite != "smoke" {
		return fmt.Errorf("QA suite must be smoke")
	}
	if req.Suite != "" && req.Kind != OperationQAStart && req.Kind != OperationQADryRun {
		return fmt.Errorf("QA suite is valid only for start or dry-run")
	}
	if req.Suite != "" && req.Task != "" {
		return fmt.Errorf("QA suite and shard focus are mutually exclusive")
	}
	if req.Task != "" && req.Kind != OperationQAStart && req.Kind != OperationQAResume {
		return fmt.Errorf("QA shard is valid only for start or resume")
	}
	return nil
}

func (u dashboardUseCases) RunOperation(ctx context.Context, req OperationRequest, emit func(OperationEvent)) (OperationResult, error) {
	expected := req.ExpectedFingerprint
	req.ExpectedFingerprint = ""
	prepared, err := u.PrepareOperation(ctx, req)
	if err != nil {
		return failedOperation(OperationResult{Subject: operationFirstNonEmpty(req.Project+"/"+req.Sprint, req.Study)}, err)
	}
	if expected != "" && expected != prepared.InputFingerprint {
		return failedOperation(OperationResult{Subject: prepared.Subject}, ErrStaleOperation)
	}
	req = prepared.Request
	if emit == nil {
		emit = func(OperationEvent) {}
	}
	emit(OperationEvent{State: OperationRunning, Stage: req.Stage, Message: "operation started"})
	if err := ctx.Err(); err != nil {
		return OperationResult{State: OperationCancelled}, err
	}
	ss := u.sprintService()
	result := OperationResult{State: OperationComplete, Subject: operationFirstNonEmpty(req.Project+"/"+req.Sprint, req.Study)}
	stage := sprint.PlanningStage(req.Stage)
	switch req.Kind {
	case OperationValidate:
		validationReq := ValidationRequest{Project: req.Project, Sprint: req.Sprint, Study: req.Study, Stage: req.Stage}
		switch {
		case req.Study != "":
			validationReq.Subject = ValidationStudy
		case req.Sprint != "":
			validationReq.Subject = ValidationSprint
		default:
			validationReq.Subject = ValidationProject
		}
		validation, err := u.Validate(ctx, validationReq)
		if err != nil {
			return failedOperation(result, err)
		}
		result.Message = validation.Status
		result.Findings = append(result.Findings, validation.Findings...)
	case OperationSprintStatus:
		r, err := ss.Status(req.Project, req.Sprint)
		if err != nil {
			return failedOperation(result, err)
		}
		result.Message = summarizeSprintStatus(r)
	case OperationPrompt:
		p, err := promptSprintStage(ss, req.Project, req.Sprint, stage)
		if err != nil {
			return failedOperation(result, err)
		}
		result.Content, result.Truncated = boundContent(p.Prompt)
	case OperationFlowDryRun:
		r, err := runSprintFlow(ctx, ss, req.Project, req.Sprint, sprint.FlowRequest{To: stage, DryRun: true})
		if err != nil {
			result = operationWithSprintFindings(result, r.Findings)
			return failedOperation(result, err)
		}
		result.Content, result.Truncated = boundContent(r.Message)
		result.Message = fmt.Sprintf("flow to %s dry run", stage)
	case OperationStageDryRun:
		r, err := ss.FlowStage(ctx, req.Project, req.Sprint, sprint.FlowRequest{To: stage, DryRun: true})
		if err != nil {
			result = operationWithSprintFindings(result, r.Findings)
			return failedOperation(result, err)
		}
		result.Content, result.Truncated = boundContent(r.Message)
		result.Message = fmt.Sprintf("single-stage %s dry run", stage)
	case OperationExecuteDryRun:
		r, err := ss.Execute(ctx, req.Project, req.Sprint, sprint.ExecuteRequest{DryRun: true, TaskID: req.Task})
		if err != nil {
			result = operationWithSprintFindings(result, r.Findings)
			return failedOperation(result, err)
		}
		result.Content, result.Truncated = boundContent(r.Prompt)
		result.Message = r.Message
	case OperationExecuteStatus:
		r, err := ss.Status(req.Project, req.Sprint)
		if err != nil {
			return failedOperation(result, err)
		}
		execute := summarizeExecute(r.ExecuteState)
		if !execute.Available {
			result.Message = execute.Message
		} else {
			result.Message = fmt.Sprintf("%d total: %d pending, %d running, %d complete, %d failed, %d cancelled", execute.Total, execute.Pending, execute.Running, execute.Complete, execute.Failed, execute.Cancelled)
		}
	case OperationReviewDryRun:
		r, err := ss.Review(ctx, req.Project, req.Sprint, sprint.ReviewRequest{DryRun: true, Concurrency: req.Parallelism})
		if err != nil {
			return failedOperation(result, err)
		}
		result.Content, result.Truncated = boundContent(r.Prompt)
		result.Message = r.Message
	case OperationReviewStatus:
		r, err := ss.Status(req.Project, req.Sprint)
		if err != nil {
			return failedOperation(result, err)
		}
		result.Message = fmt.Sprintf("%s verdict=%s fresh=%t next=%s", r.Verification.Review.ExecutionStatus, r.Verification.Review.Verdict, r.Verification.Review.Fresh, r.Verification.Review.NextAction)
	case OperationSmokeStatus:
		r, err := ss.VerificationStatus(req.Project, req.Sprint)
		if err != nil {
			return failedOperation(result, err)
		}
		result.Message = fmt.Sprintf("%s verdict=%s fresh=%t run=%s issues=%d assessment=%s next=%s", r.Smoke.ExecutionStatus, r.Smoke.Verdict, r.Smoke.Fresh, r.Smoke.RunID, len(r.Smoke.Issues), r.Assessment, r.NextAction)
	case OperationSmokeDryRun:
		r, err := ss.RunSmoke(ctx, req.Project, req.Sprint, sprint.SmokeRequest{Level: req.Level, Suite: req.Suite, Test: req.Test, ForceReview: req.ForceReview, OverrideConfirmed: req.ForceReview, OverrideRationale: req.OverrideRationale, DryRun: true})
		if err != nil {
			return failedOperation(result, err)
		}
		result.Message = fmt.Sprintf("%s %s: %s", r.ScopeKind, r.Scope, r.ScopeRationale)
		result.Content, result.Truncated = boundContent(sprint.RenderSmoke(r))
	case OperationQAStatus:
		qa, err := u.QAStatus(ctx, QARequest{Project: req.Project, Sprint: req.Sprint})
		if err != nil {
			return failedOperation(result, err)
		}
		result.Message = fmt.Sprintf("phase=%s fresh=%t shards=%d/%d next=%s", qa.Phase, qa.Fresh, qa.CompletedShards, qa.TotalShards, qa.NextAction)
	case OperationQADryRun:
		if req.Suite == "smoke" {
			smoke, err := ss.RunSmoke(ctx, req.Project, req.Sprint, sprint.SmokeRequest{DryRun: true})
			if err != nil {
				return failedOperation(result, err)
			}
			result.Message = fmt.Sprintf("smoke suite ready: %s %s", smoke.ScopeKind, smoke.Scope)
			result.Content, result.Truncated = boundContent(sprint.RenderSmoke(smoke))
			break
		}
		qa, err := u.QAMap(ctx, QARequest{Project: req.Project, Sprint: req.Sprint})
		if err != nil {
			return failedOperation(result, err)
		}
		data, _ := json.MarshalIndent(qa, "", "  ")
		result.Content, result.Truncated = boundContent(string(data))
		result.Message = "read-only QA map ready"
	case OperationQARecover:
		qa, err := u.RecoverQA(ctx, QARequest{Project: req.Project, Sprint: req.Sprint})
		if err != nil {
			return failedOperation(result, err)
		}
		result.Message = fmt.Sprintf("phase=%s next=%s", qa.Phase, qa.NextAction)
	case OperationVerifyDryRun:
		r, err := ss.Verify(ctx, req.Project, req.Sprint, sprint.VerifyRequest{To: sprint.PlanningStage(req.Stage), DryRun: true, Review: sprint.ReviewRequest{DryRun: true, Focus: req.ReviewFocus, Restart: req.RestartReview}, Smoke: sprint.SmokeRequest{Level: req.Level, Suite: req.Suite, Test: req.Test, ForceReview: req.ForceReview, OverrideConfirmed: req.ForceReview, OverrideRationale: req.OverrideRationale, DryRun: true}})
		if err != nil {
			return failedOperation(result, err)
		}
		result.Message = fmt.Sprintf("assessment=%s next=%s", r.Verification.Assessment, r.Verification.NextAction)
	default:
		if u.runner == nil {
			return failedOperation(result, fmt.Errorf("runtime-backed operation is unavailable without configured composition"))
		}
		return u.runner(ctx, req, emit)
	}
	emit(OperationEvent{State: OperationComplete, Stage: req.Stage, Message: operationFirstNonEmpty(result.Message, "operation complete")})
	return result, nil
}

func normalizeOperationRequest(req OperationRequest) OperationRequest {
	req.Project = strings.TrimSpace(req.Project)
	req.Sprint = strings.TrimSpace(req.Sprint)
	req.Study = strings.TrimSpace(req.Study)
	req.Stage = strings.TrimSpace(req.Stage)
	req.Task = strings.TrimSpace(req.Task)
	req.Model = strings.TrimSpace(req.Model)
	req.Level = strings.TrimSpace(req.Level)
	req.Suite = strings.TrimSpace(req.Suite)
	req.Test = strings.TrimSpace(req.Test)
	req.Timeout = strings.TrimSpace(req.Timeout)
	req.OverrideRationale = strings.TrimSpace(req.OverrideRationale)
	req.ReviewFocus = normalizedStrings(req.ReviewFocus)
	req.Sources = normalizedStrings(req.Sources)
	req.Dimensions = normalizedStrings(req.Dimensions)
	return req
}

func validateOperationScope(req OperationRequest) error {
	for name, value := range map[string]string{"project": req.Project, "sprint": req.Sprint, "study": req.Study} {
		if value == "" {
			continue
		}
		if value == "." || value == ".." || len(value) > 128 || strings.ContainsAny(value, `/\\`) {
			return fmt.Errorf("invalid operation %s reference", name)
		}
		for _, r := range value {
			if (r >= 'a' && r <= 'z') || (r >= 'A' && r <= 'Z') || (r >= '0' && r <= '9') || r == '.' || r == '_' || r == '-' {
				continue
			}
			return fmt.Errorf("invalid operation %s reference", name)
		}
	}
	return nil
}

func normalizedStrings(values []string) []string {
	seen := make(map[string]struct{}, len(values))
	out := make([]string, 0, len(values))
	for _, value := range values {
		value = strings.TrimSpace(value)
		if value == "" {
			continue
		}
		if _, ok := seen[value]; ok {
			continue
		}
		seen[value] = struct{}{}
		out = append(out, value)
	}
	sort.Strings(out)
	return out
}

func canonicalOperationRequest(req OperationRequest) (string, error) {
	req.ExpectedFingerprint = ""
	data, err := json.Marshal(req)
	if err != nil {
		return "", fmt.Errorf("canonicalize operation: %w", err)
	}
	return string(data), nil
}

func operationPrerequisites(req OperationRequest) []string {
	prerequisites := []string{"workspace readable"}
	if req.Project != "" {
		prerequisites = append(prerequisites, "project and sprint resolvable")
	}
	if req.Study != "" {
		prerequisites = append(prerequisites, "study resolvable")
	}
	if req.Kind == OperationExecuteStart || req.Kind == OperationExecuteResume {
		prerequisites = append(prerequisites, "validated plan", "approved target implementation directory")
	}
	if req.Kind == OperationQAStart || req.Kind == OperationQAResume || req.Kind == OperationQADryRun || req.Kind == OperationQARecover {
		prerequisites = append(prerequisites, "complete execute evidence", "current Conformance Review", "approved read-only target")
	}
	return prerequisites
}

func operationRuntimeIdentity(req OperationRequest, stages map[sprint.PlanningStage]sprint.StageRuntime) string {
	if req.Model != "" {
		return "requested model " + req.Model
	}
	stage := sprint.PlanningStage(req.Stage)
	switch req.Kind {
	case OperationExecuteStart, OperationExecuteResume:
		stage = sprint.StageExecute
	case OperationReviewStart:
		stage = sprint.StageReview
	case OperationSmokeStart, OperationVerifyStart:
		stage = sprint.StageSmoke
	case OperationQAStart, OperationQAResume:
		if req.Suite == "smoke" {
			return "configured smoke author and harness"
		}
		return "configured QA runtime"
	}
	if runtime, ok := stages[stage]; ok && (runtime.Model != "" || runtime.Variant != "") {
		return strings.TrimSpace(runtime.Model + " variant=" + runtime.Variant)
	}
	if req.Kind == OperationSmokeStart {
		return "configured smoke author and harness"
	}
	return "effective workspace runtime configuration"
}

func governedOperationInputs(req OperationRequest) []string {
	if req.Project != "" {
		base := filepath.ToSlash(filepath.Join("projects", req.Project))
		inputs := []string{
			filepath.ToSlash(filepath.Join(base, "project-index.md")),
			filepath.ToSlash(filepath.Join(base, "roadmap.md")),
			filepath.ToSlash(filepath.Join(base, "docs")),
			filepath.ToSlash(filepath.Join(base, "sprints", req.Sprint, "requirements.md")),
			filepath.ToSlash(filepath.Join(base, "sprints", req.Sprint, "code-context.md")),
			filepath.ToSlash(filepath.Join(base, "sprints", req.Sprint, "sprint-index.md")),
			filepath.ToSlash(filepath.Join(base, "sprints", req.Sprint, "technical-handbook.md")),
			filepath.ToSlash(filepath.Join(base, "sprints", req.Sprint, "reasoning.md")),
			filepath.ToSlash(filepath.Join(base, "sprints", req.Sprint, "plan.md")),
		}
		switch req.Kind {
		case OperationQADryRun, OperationQAStart, OperationQAResume, OperationQARecover, OperationQAStatus:
			inputs = append(inputs,
				filepath.ToSlash(filepath.Join(base, "sprints", req.Sprint, "execute.md")),
				filepath.ToSlash(filepath.Join(base, "sprints", req.Sprint, ".run-state.json")),
				filepath.ToSlash(filepath.Join(base, "sprints", req.Sprint, "review.md")),
				filepath.ToSlash(filepath.Join(base, "sprints", req.Sprint, "flow-state.json")),
			)
		}
		return append([]string{"ultraplan.yml"}, inputs...)
	}
	if req.Study != "" {
		return []string{
			"ultraplan.yml",
			filepath.ToSlash(filepath.Join("studies", req.Study, "study.yml")),
			filepath.ToSlash(filepath.Join("studies", req.Study, "study.yaml")),
			filepath.ToSlash(filepath.Join("studies", req.Study, ".ultraplan", "run-state.json")),
		}
	}
	return nil
}

func fingerprintOperationInputs(root, canonical string, inputs []string) (string, error) {
	hash := sha256.New()
	_, _ = hash.Write([]byte(canonical))
	for _, rel := range inputs {
		path := filepath.Join(root, filepath.FromSlash(rel))
		info, err := os.Lstat(path)
		if errors.Is(err, fs.ErrNotExist) {
			continue
		}
		if err != nil {
			return "", fmt.Errorf("inspect governed input %s: %w", rel, err)
		}
		if info.Mode()&os.ModeSymlink != 0 {
			return "", fmt.Errorf("governed input %s must not be a symbolic link", rel)
		}
		if info.IsDir() {
			var files []string
			if err := filepath.WalkDir(path, func(item string, entry fs.DirEntry, walkErr error) error {
				if walkErr != nil {
					return walkErr
				}
				if entry.Type()&os.ModeSymlink != 0 {
					return fmt.Errorf("governed input %s must not contain symbolic links", rel)
				}
				if !entry.IsDir() {
					files = append(files, item)
				}
				return nil
			}); err != nil {
				return "", fmt.Errorf("scan governed input %s: %w", rel, err)
			}
			sort.Strings(files)
			for _, item := range files {
				itemRel, _ := filepath.Rel(root, item)
				if err := hashOperationFile(hash, item, filepath.ToSlash(itemRel)); err != nil {
					return "", err
				}
			}
			continue
		}
		if err := hashOperationFile(hash, path, rel); err != nil {
			return "", err
		}
	}
	return "sha256:" + hex.EncodeToString(hash.Sum(nil)), nil
}

func hashOperationFile(hash interface{ Write([]byte) (int, error) }, path, rel string) error {
	data, err := os.ReadFile(path)
	if err != nil {
		return fmt.Errorf("read governed input %s: %w", rel, err)
	}
	_, _ = hash.Write([]byte("\x00" + rel + "\x00"))
	_, _ = hash.Write(data)
	return nil
}

func summarizeSprintStatus(status sprint.StatusSummary) string {
	parts := make([]string, 0, len(status.Stages)+2)
	for _, stage := range status.Stages {
		parts = append(parts, fmt.Sprintf("%s=%s", stage.Stage, stage.Status))
	}
	execute := summarizeExecute(status.ExecuteState)
	if execute.Available {
		parts = append(parts, fmt.Sprintf("execute=%d/%d complete (%d failed, %d cancelled)", execute.Complete, execute.Total, execute.Failed, execute.Cancelled))
	} else {
		parts = append(parts, "execute=not started")
	}
	if status.Review == nil {
		parts = append(parts, "review=not started")
	} else {
		parts = append(parts, fmt.Sprintf("review=%s verdict=%s stale=%t", status.Review.Status, status.Review.Verdict, status.Review.Stale))
	}
	if status.Smoke == nil {
		parts = append(parts, "smoke=not started")
	} else {
		parts = append(parts, fmt.Sprintf("smoke=%s verdict=%s stale=%t", status.Smoke.Status, status.Smoke.Verdict, status.Smoke.Stale))
	}
	parts = append(parts, fmt.Sprintf("assessment=%s next=%s", status.Verification.Assessment, status.Verification.NextAction))
	return strings.Join(parts, "\n")
}

func operationWithSprintFindings(result OperationResult, findings []sprint.ValidationFinding) OperationResult {
	for _, finding := range findings {
		result.Findings = append(result.Findings, sprintFinding(finding))
	}
	return result
}
func failedOperation(r OperationResult, err error) (OperationResult, error) {
	if errors.Is(err, context.Canceled) {
		r.State = OperationCancelled
	} else {
		r.State = OperationFailed
	}
	cause := displaySafe(err.Error())
	code, category, guidance := "internal.error", "internal", "Inspect durable state and retry after correcting the reported cause."
	if smokeErr, ok := sprint.AsSmokeError(err); ok {
		code, category, guidance = smokeErr.Code, smokeErr.Category, smokeErr.Guidance
		r.Message = operationFailureMessage(category)
		r.Error = &OperationError{Code: code, Category: category, Operation: "smoke", Component: "sprint", Message: r.Message, Cause: cause, Guidance: guidance, Retryable: category == "process" || category == "timeout"}
		return r, err
	}
	if qaErr, ok := sprint.AsQAError(err); ok {
		category = string(qaErr.Category)
		code = "qa." + category
		guidance = qaErr.Recovery
		switch qaErr.Category {
		case sprint.QAErrorRuntimeUnavailable, sprint.QAErrorPersistenceFailure:
			category = "runtime"
		case sprint.QAErrorConflict:
			category = "concurrency"
		default:
			category = "validation"
		}
		r.Message = operationFailureMessage(category)
		r.Error = &OperationError{Code: code, Category: category, Operation: "qa", Component: "sprint", Message: r.Message, Cause: cause, Guidance: guidance, Retryable: qaErr.Category == sprint.QAErrorRuntimeUnavailable || qaErr.Category == sprint.QAErrorConflict}
		return r, err
	}
	var projectRef project.RefError
	var sprintRef sprint.RefError
	switch {
	case errors.Is(err, context.Canceled):
		code, category, guidance = "workflow.cancelled", "cancellation", "Resume the operation when ready."
	case errors.Is(err, sprint.ErrFlowStateMalformed), errors.Is(err, sprint.ErrFlowStateUnsupported),
		errors.Is(err, sprint.ErrExecuteRunStateMissing), errors.Is(err, sprint.ErrExecuteRunStateMalformed), errors.Is(err, sprint.ErrExecuteRunStateUnsupported),
		errors.As(err, &projectRef), errors.As(err, &sprintRef), len(r.Findings) > 0:
		code, category, guidance = "validation.reference", "validation", "Complete or repair the reported governed evidence, inspect validation findings, and retry."
	case errors.Is(err, sprint.ErrVerificationConflict), errors.Is(err, ErrStaleOperation):
		code, category, guidance = "workflow.locked", "concurrency", "Inspect the active or stale study lock before retrying."
	}
	r.Message = operationFailureMessage(category)
	r.Error = &OperationError{Code: code, Category: category, Operation: "workflow.operation", Component: "app", Message: r.Message, Cause: cause, Guidance: guidance, Retryable: category == "runtime" || category == "concurrency"}
	return r, err
}

func operationFailureMessage(category string) string {
	switch category {
	case "cancellation":
		return "Operation cancelled."
	case "validation":
		return "Operation failed validation."
	case "runtime", "process", "timeout":
		return "Runtime operation failed."
	case "concurrency":
		return "Operation could not acquire mutation ownership."
	default:
		return "Operation failed."
	}
}
func boundContent(s string) (string, bool) {
	if len(s) > PreviewByteLimit {
		return s[:PreviewByteLimit], true
	}
	return s, false
}
func operationFirstNonEmpty(a, b string) string {
	if strings.Trim(a, "/") != "" {
		return strings.Trim(a, "/")
	}
	return b
}
func promptSprintStage(s sprint.Service, p, sp string, stage sprint.PlanningStage) (sprint.PromptPreview, error) {
	switch stage {
	case sprint.StageRequirements:
		return s.PromptRequirements(p, sp)
	case sprint.StageCodeContext:
		return s.PromptCodeContext(p, sp)
	case sprint.StageSprintIndex:
		return s.PromptSprintIndex(p, sp)
	case sprint.StageTechnicalHandbook:
		return s.PromptTechnicalHandbook(p, sp)
	case sprint.StageAreaReasoning:
		return s.PromptAreaReasoning(p, sp)
	case sprint.StageReasoning:
		return s.PromptReasoning(p, sp)
	case sprint.StagePlan:
		return s.PromptPlan(p, sp)
	case sprint.StageExecute:
		return s.PromptExecute(p, sp, sprint.ExecuteRequest{})
	case sprint.StageReview:
		return s.PromptReview(p, sp, sprint.ReviewRequest{})
	default:
		return sprint.PromptPreview{}, fmt.Errorf("unsupported prompt stage %q", stage)
	}
}

type ValidationSubject string

const (
	ValidationProject ValidationSubject = "project"
	ValidationStudy   ValidationSubject = "study"
	ValidationSprint  ValidationSubject = "sprint"
)

type ValidationRequest struct {
	Subject ValidationSubject
	Project string
	Study   string
	Sprint  string
	Stage   string
}

type ValidationOperationResult struct {
	Operation string
	Subject   string
	Status    string
	Findings  []DisplayFinding
}

func NewOperationalUseCases(root string) OperationalUseCases { return dashboardUseCases{root: root} }

func (u dashboardUseCases) Validate(ctx context.Context, req ValidationRequest) (ValidationOperationResult, error) {
	if err := ctx.Err(); err != nil {
		return ValidationOperationResult{}, err
	}
	result := ValidationOperationResult{Operation: "validate", Status: "valid"}
	switch req.Subject {
	case ValidationProject:
		ref := strings.TrimSpace(req.Project)
		validation, err := project.NewService(u.root).Validate(ref)
		if err != nil {
			return result, mapProjectError("project.validate", err)
		}
		result.Subject = ref
		result.Status = string(validation.Status)
		for _, finding := range validation.Findings {
			result.Findings = append(result.Findings, projectFinding(finding))
		}
	case ValidationStudy:
		ref := strings.TrimSpace(req.Study)
		validation, err := study.NewService(u.root).ValidateStudy(ref)
		if err != nil {
			return result, mapStudyError(err)
		}
		result.Subject = ref
		result.Status = string(validation.Status)
		for _, check := range validation.Checks {
			if check.Status != study.ValidationStatusPassed {
				result.Findings = append(result.Findings, studyFinding(check))
			}
		}
		for _, report := range validation.Reports {
			for _, check := range report.Checks {
				if check.Status != study.ValidationStatusPassed {
					result.Findings = append(result.Findings, studyFinding(check))
				}
			}
		}
	case ValidationSprint:
		stage := sprint.PlanningStage(strings.TrimSpace(req.Stage))
		validation, err := validateSprintStage(u.sprintService(), req.Project, req.Sprint, stage)
		if err != nil {
			return result, mapSprintError("sprint.validate", err)
		}
		result.Subject = strings.TrimSpace(req.Project) + "/" + strings.TrimSpace(req.Sprint) + "/" + string(stage)
		if !validation.Valid() {
			result.Status = "invalid"
		}
		for _, finding := range validation.Findings {
			result.Findings = append(result.Findings, sprintFinding(finding))
		}
	default:
		return result, fmt.Errorf("validate: unsupported subject %q", req.Subject)
	}
	sort.SliceStable(result.Findings, func(i, j int) bool {
		a, b := result.Findings[i], result.Findings[j]
		if a.Path != b.Path {
			return a.Path < b.Path
		}
		if a.Section != b.Section {
			return a.Section < b.Section
		}
		return a.Problem < b.Problem
	})
	return result, nil
}

package web

import (
	"context"
	"encoding/json"
	"errors"
	"fmt"
	"sort"
	"strconv"
	"strings"
	"sync"
	"sync/atomic"
	"time"

	"github.com/Antonio7098/ultraplan-go/internal/app"
)

const (
	MaxActiveOperations        = 8
	MaxPreparations            = 128
	PreparationTTL             = 2 * time.Minute
	MaxEventsPerOperation      = 256
	MaxEventBytesPerOperation  = 256 * 1024
	MaxEncodedEventBytes       = 16 * 1024
	MaxTerminalResultBytes     = 256 * 1024
	MaxSubscribersPerOperation = 8
	MaxConcurrentStreams       = 32
	SubscriberQueueSize        = 32
	TerminalRetention          = 10 * time.Minute
	SSEHeartbeat               = 15 * time.Second
	MaxStreamLifetime          = 30 * time.Minute
)

var (
	errOperationCapacity  = errors.New("operation capacity reached")
	errSubscriberCapacity = errors.New("subscriber capacity reached")
	errServerDraining     = errors.New("server draining")
	errOperationNotFound  = errors.New("operation not found")
)

type operationDocument struct {
	ID            string              `json:"id"`
	Kind          app.OperationKind   `json:"kind"`
	State         string              `json:"state"`
	Reason        string              `json:"reason,omitempty"`
	CreatedAt     time.Time           `json:"created_at"`
	StartedAt     *time.Time          `json:"started_at,omitempty"`
	FinishedAt    *time.Time          `json:"finished_at,omitempty"`
	LastEventID   string              `json:"last_event_id"`
	DurableStatus durableStatusDTO    `json:"durable_status"`
	Result        *operationResultDTO `json:"result,omitempty"`
}

type activeOperationDTO struct {
	ID        string            `json:"id"`
	Kind      app.OperationKind `json:"kind"`
	State     string            `json:"state"`
	Project   string            `json:"project,omitempty"`
	Sprint    string            `json:"sprint,omitempty"`
	Study     string            `json:"study,omitempty"`
	StartedAt *time.Time        `json:"started_at,omitempty"`
}

type durableStatusDTO struct {
	Available   bool   `json:"available"`
	RefreshPath string `json:"refresh_path,omitempty"`
}

type operationResultDTO struct {
	State     string       `json:"state"`
	Subject   string       `json:"subject,omitempty"`
	Message   string       `json:"message,omitempty"`
	Content   string       `json:"content,omitempty"`
	Truncated bool         `json:"truncated,omitempty"`
	Findings  []findingDTO `json:"findings,omitempty"`
	Error     *errorBody   `json:"error,omitempty"`
}

type operationEvent struct {
	ID   uint64
	Name string
	Data []byte
}

type operationSubscriber struct {
	id uint64
	ch chan operationEvent
}

type operationRecord struct {
	doc         operationDocument
	session     string
	request     app.OperationRequest
	cancel      context.CancelFunc
	cancelOnce  sync.Once
	done        chan struct{}
	nextEventID uint64
	events      []operationEvent
	eventBytes  int
	subscribers map[uint64]*operationSubscriber
	nextSubID   uint64
	dedupKey    string
}

type operationHub struct {
	rootCtx context.Context
	ops     app.WebOperations
	now     func() time.Time
	id      func() string

	mu       sync.Mutex
	records  map[string]*operationRecord
	dedup    map[string]string
	active   int
	streams  int
	draining bool
	counters operationCounters
}

type operationCounters struct {
	starts             atomic.Int64
	active             atomic.Int64
	terminal           atomic.Int64
	capacityRejections atomic.Int64
	cancellations      atomic.Int64
	activeStreams      atomic.Int64
	slowSubscribers    atomic.Int64
	replayGaps         atomic.Int64
	projectionDrops    atomic.Int64
	shutdownCleanups   atomic.Int64
}

func newOperationHub(rootCtx context.Context, ops app.WebOperations, now func() time.Time, id func() string) *operationHub {
	if rootCtx == nil {
		rootCtx = context.Background()
	}
	if now == nil {
		now = time.Now
	}
	if id == nil {
		id = randomRequestID
	}
	return &operationHub{rootCtx: rootCtx, ops: ops, now: now, id: id, records: make(map[string]*operationRecord), dedup: make(map[string]string)}
}

func (h *operationHub) start(session string, prepared app.Confirmation) (operationDocument, error) {
	return h.startConfirmed(session, "", func() (app.Confirmation, error) { return prepared, nil })
}

func (h *operationHub) startConfirmed(session, dedupKey string, confirm func() (app.Confirmation, error)) (operationDocument, error) {
	h.mu.Lock()
	defer h.mu.Unlock()
	h.reapLocked()
	if id := h.dedup[dedupKey]; dedupKey != "" && id != "" {
		if record := h.records[id]; record != nil && record.session == session {
			return cloneOperationDocument(record.doc), nil
		}
		delete(h.dedup, dedupKey)
	}
	if h.draining {
		h.counters.capacityRejections.Add(1)
		return operationDocument{}, errServerDraining
	}
	if h.active >= MaxActiveOperations {
		h.counters.capacityRejections.Add(1)
		return operationDocument{}, errOperationCapacity
	}
	if h.ops == nil {
		return operationDocument{}, errors.New("operation capability unavailable")
	}
	prepared, err := confirm()
	if err != nil {
		return operationDocument{}, err
	}
	id := "op_" + h.id()
	for h.records[id] != nil {
		id = "op_" + h.id()
	}
	created := h.now().UTC()
	ctx, cancel := context.WithCancel(h.rootCtx)
	if manager, ok := h.ops.(app.DurableOperationManager); ok {
		accepted, acceptErr := manager.AcceptOperation(ctx, prepared, dedupKey)
		if acceptErr != nil {
			if !errors.Is(acceptErr, app.ErrWebUnavailable) {
				cancel()
				return operationDocument{}, acceptErr
			}
		} else {
			id = accepted.RunID
			if accepted.Context != nil {
				ctx = accepted.Context
			}
			if accepted.Existing {
				doc := operationDocument{ID: id, Kind: prepared.Request.Kind, State: accepted.Lifecycle, CreatedAt: created, DurableStatus: durableStatusDTO{Available: true, RefreshPath: "/runs/" + id}}
				cancel()
				return doc, nil
			}
		}
	}
	record := &operationRecord{
		doc: operationDocument{
			ID: id, Kind: prepared.Request.Kind, State: "accepted", CreatedAt: created,
			DurableStatus: durableStatusDTO{Available: prepared.DurableRefreshPath != "", RefreshPath: prepared.DurableRefreshPath},
		},
		session: session, request: prepared.Request, cancel: cancel, done: make(chan struct{}),
		subscribers: make(map[uint64]*operationSubscriber), dedupKey: dedupKey,
	}
	h.records[id] = record
	if dedupKey != "" {
		h.dedup[dedupKey] = id
	}
	h.active++
	h.counters.starts.Add(1)
	h.counters.active.Add(1)
	h.appendEventLocked(record, "snapshot", map[string]any{"state": "accepted"})
	doc := cloneOperationDocument(record.doc)
	go h.run(ctx, record)
	return doc, nil
}

func (h *operationHub) run(ctx context.Context, record *operationRecord) {
	started := h.now().UTC()
	h.mu.Lock()
	if record.doc.State == "accepted" {
		record.doc.State = "running"
		record.doc.StartedAt = &started
		h.appendEventLocked(record, "progress", map[string]any{"message": "operation started", "state": "running"})
	}
	h.mu.Unlock()

	result, runErr := h.ops.RunOperation(ctx, record.request, func(event app.OperationEvent) {
		h.publishAppEvent(record, event)
	})
	if manager, ok := h.ops.(app.DurableOperationManager); ok {
		finishCtx, cancel := context.WithTimeout(context.Background(), 30*time.Second)
		finishErr := manager.FinishOperation(finishCtx, record.doc.ID, result.State, runErr)
		cancel()
		if finishErr != nil && !errors.Is(finishErr, app.ErrWebUnavailable) {
			runErr = errors.Join(runErr, finishErr)
		}
	}
	h.finish(record, result, runErr)
}

func (h *operationHub) publishAppEvent(record *operationRecord, event app.OperationEvent) {
	if manager, ok := h.ops.(app.DurableOperationManager); ok {
		committed, err := manager.RecordOperationEvent(context.Background(), record.doc.ID, event)
		if err != nil && !errors.Is(err, app.ErrWebUnavailable) {
			record.cancel()
			return
		}
		if err == nil && !committed {
			return
		}
	}
	name := "progress"
	if event.State == app.OperationFailed {
		name = "warning"
	}
	payload := map[string]any{
		"state": string(event.State), "stage": safeWebText(event.Stage), "task": safeWebText(event.Task),
		"message": safeWebText(event.Message), "completed": event.Completed, "total": event.Total, "attempt": event.Attempt,
		"event_kind": safeWebText(event.EventKind), "event_type": safeWebText(event.EventType), "tool": safeWebText(event.Tool), "action": safeWebText(event.Action),
		"tool_call_id": safeWebText(event.ToolCallID), "tool_status": safeWebText(event.ToolStatus),
		"tool_arguments": event.ToolArguments, "tool_result": event.ToolResult, "tool_error": event.ToolError,
		"reason": safeWebText(event.Reason), "detail": safeWebText(event.Detail),
		"runtime_attempts": event.RuntimeAttempts, "turns": event.Turns, "turns_known": event.TurnsKnown,
		"tokens": event.Tokens, "tokens_known": event.TokensKnown, "duration": safeWebText(event.Duration),
		"provider": safeWebText(event.Provider), "model": safeWebText(event.Model), "harness": safeWebText(event.Harness), "cost": safeWebText(event.Cost), "runtime_events": event.RuntimeEvents,
	}
	h.mu.Lock()
	defer h.mu.Unlock()
	if terminalOperationState(record.doc.State) {
		return
	}
	h.appendEventLocked(record, name, payload)
}

func (h *operationHub) finish(record *operationRecord, result app.OperationResult, runErr error) {
	finished := h.now().UTC()
	h.mu.Lock()
	defer h.mu.Unlock()
	if terminalOperationState(record.doc.State) {
		return
	}
	state := "succeeded"
	switch {
	case errors.Is(runErr, context.Canceled), result.State == app.OperationCancelled:
		state = "cancelled"
	case runErr != nil, result.State == app.OperationFailed:
		state = "failed"
	case result.State == app.OperationPartial:
		state = "interrupted"
	}
	record.doc.State = state
	record.doc.FinishedAt = &finished
	record.doc.Result = projectOperationResult(result)
	h.appendEventLocked(record, "terminal", map[string]any{"state": state, "reason": record.doc.Reason, "result": record.doc.Result})
	h.active--
	h.counters.active.Add(-1)
	h.counters.terminal.Add(1)
	close(record.done)
	for id, subscriber := range record.subscribers {
		close(subscriber.ch)
		delete(record.subscribers, id)
		h.streams--
		h.counters.activeStreams.Add(-1)
	}
}

func (h *operationHub) status(session, id string) (operationDocument, error) {
	h.mu.Lock()
	defer h.mu.Unlock()
	h.reapLocked()
	record := h.records[id]
	if record == nil || record.session != session {
		return operationDocument{}, errOperationNotFound
	}
	return cloneOperationDocument(record.doc), nil
}

func (h *operationHub) activeOperations(session string) []activeOperationDTO {
	h.mu.Lock()
	defer h.mu.Unlock()
	h.reapLocked()
	result := make([]activeOperationDTO, 0, h.active)
	for _, record := range h.records {
		if record.session != session || terminalOperationState(record.doc.State) {
			continue
		}
		result = append(result, activeOperationDTO{
			ID: record.doc.ID, Kind: record.doc.Kind, State: record.doc.State,
			Project: record.request.Project, Sprint: record.request.Sprint, Study: record.request.Study,
			StartedAt: record.doc.StartedAt,
		})
	}
	sort.Slice(result, func(i, j int) bool {
		left, right := result[i].StartedAt, result[j].StartedAt
		if left == nil || right == nil {
			return left != nil
		}
		return left.After(*right)
	})
	return result
}

func (h *operationHub) cancelOperation(session, id, reason string) (operationDocument, bool, error) {
	h.mu.Lock()
	record := h.records[id]
	if record == nil || (session != "" && record.session != session) {
		h.mu.Unlock()
		return operationDocument{}, false, errOperationNotFound
	}
	if terminalOperationState(record.doc.State) {
		doc := cloneOperationDocument(record.doc)
		h.mu.Unlock()
		return doc, false, nil
	}
	requested := false
	record.cancelOnce.Do(func() {
		requested = true
		record.doc.State = "cancelling"
		record.doc.Reason = canonicalCancelReason(reason)
		h.appendEventLocked(record, "cancel_requested", map[string]any{"reason": record.doc.Reason})
	})
	doc := cloneOperationDocument(record.doc)
	cancel := record.cancel
	h.mu.Unlock()
	if requested {
		h.counters.cancellations.Add(1)
		cancel()
	}
	return doc, requested, nil
}

func (h *operationHub) subscribe(session, id string, lastID uint64) ([]operationEvent, <-chan operationEvent, func(), error) {
	h.mu.Lock()
	defer h.mu.Unlock()
	h.reapLocked()
	record := h.records[id]
	if record == nil || record.session != session {
		return nil, nil, nil, errOperationNotFound
	}
	if h.streams >= MaxConcurrentStreams || len(record.subscribers) >= MaxSubscribersPerOperation {
		h.counters.capacityRejections.Add(1)
		return nil, nil, nil, errSubscriberCapacity
	}
	if lastID > 0 && len(record.events) > 0 && lastID < record.events[0].ID-1 {
		h.counters.replayGaps.Add(1)
		h.appendEventLocked(record, "recovery_required", map[string]any{
			"oldest_retained_id": strconv.FormatUint(record.events[0].ID, 10),
			"newest_retained_id": strconv.FormatUint(record.nextEventID, 10),
			"refresh_path":       record.doc.DurableStatus.RefreshPath,
		})
		h.appendEventLocked(record, "snapshot", map[string]any{"state": record.doc.State, "reason": record.doc.Reason})
	}
	replay := make([]operationEvent, 0, len(record.events))
	for _, event := range record.events {
		if event.ID > lastID {
			replay = append(replay, event)
		}
	}
	record.nextSubID++
	sub := &operationSubscriber{id: record.nextSubID, ch: make(chan operationEvent, SubscriberQueueSize)}
	if terminalOperationState(record.doc.State) {
		close(sub.ch)
	} else {
		record.subscribers[sub.id] = sub
		h.streams++
		h.counters.activeStreams.Add(1)
	}
	var once sync.Once
	unsubscribe := func() {
		once.Do(func() {
			h.mu.Lock()
			defer h.mu.Unlock()
			if current, ok := record.subscribers[sub.id]; ok {
				delete(record.subscribers, sub.id)
				h.streams--
				h.counters.activeStreams.Add(-1)
				close(current.ch)
			}
		})
	}
	return replay, sub.ch, unsubscribe, nil
}

func (h *operationHub) appendEventLocked(record *operationRecord, name string, payload any) {
	name = stableOperationEventName(name)
	record.nextEventID++
	body := map[string]any{
		"operation_id": record.doc.ID,
		"time":         h.now().UTC().Format(time.RFC3339Nano),
		"sequence":     record.nextEventID,
		"payload":      payload,
	}
	data, err := json.Marshal(body)
	if err != nil {
		h.counters.projectionDrops.Add(1)
		return
	}
	if len(data) > MaxEncodedEventBytes {
		data, _ = json.Marshal(map[string]any{
			"operation_id": record.doc.ID, "time": h.now().UTC().Format(time.RFC3339Nano),
			"sequence": record.nextEventID, "payload": map[string]any{"message": "event projection exceeded the safe size limit"},
		})
		name = "warning"
	}
	event := operationEvent{ID: record.nextEventID, Name: name, Data: data}
	record.events = append(record.events, event)
	record.eventBytes += len(data)
	for len(record.events) > MaxEventsPerOperation || record.eventBytes > MaxEventBytesPerOperation {
		record.eventBytes -= len(record.events[0].Data)
		record.events = record.events[1:]
	}
	record.doc.LastEventID = strconv.FormatUint(event.ID, 10)
	for id, subscriber := range record.subscribers {
		select {
		case subscriber.ch <- event:
		default:
			close(subscriber.ch)
			delete(record.subscribers, id)
			h.streams--
			h.counters.activeStreams.Add(-1)
			h.counters.slowSubscribers.Add(1)
		}
	}
}

func stableOperationEventName(name string) string {
	switch name {
	case "snapshot", "progress", "warning", "finding", "artifact", "cancel_requested", "recovery_required", "terminal":
		return name
	default:
		return "progress"
	}
}

func (h *operationHub) drainAndWait(ctx context.Context) error {
	h.mu.Lock()
	h.draining = true
	var records []*operationRecord
	for _, record := range h.records {
		if !terminalOperationState(record.doc.State) {
			records = append(records, record)
		}
	}
	h.mu.Unlock()
	for _, record := range records {
		_, _, _ = h.cancelOperation("", record.doc.ID, "server_shutdown")
	}
	h.counters.shutdownCleanups.Add(int64(len(records)))
	for _, record := range records {
		select {
		case <-record.done:
		case <-ctx.Done():
			persistErr := h.persistCleanupUncertain(records)
			h.markCleanupUncertain(records)
			return errors.Join(ctx.Err(), persistErr)
		}
	}
	return nil
}

func (h *operationHub) persistCleanupUncertain(records []*operationRecord) error {
	recorder, ok := h.ops.(app.OperationCleanupRecorder)
	if !ok {
		return errors.New("operation capability cannot persist cleanup uncertainty")
	}
	var result error
	for _, record := range records {
		h.mu.Lock()
		terminal := terminalOperationState(record.doc.State)
		h.mu.Unlock()
		if terminal {
			continue
		}
		persistCtx, cancel := context.WithTimeout(context.Background(), time.Second)
		err := recorder.RecordOperationCleanupUncertain(persistCtx, app.OperationCleanupUncertain{
			OperationID: record.doc.ID,
			Request:     record.request,
			Reason:      "server_shutdown",
			RecordedAt:  h.now().UTC(),
		})
		cancel()
		if err != nil {
			result = errors.Join(result, fmt.Errorf("persist cleanup uncertainty for %s: %w", record.doc.ID, err))
		}
	}
	return result
}

func (h *operationHub) markCleanupUncertain(records []*operationRecord) {
	h.mu.Lock()
	defer h.mu.Unlock()
	finished := h.now().UTC()
	for _, record := range records {
		if terminalOperationState(record.doc.State) {
			continue
		}
		record.doc.State = "cleanup_uncertain"
		record.doc.Reason = "server_shutdown"
		record.doc.FinishedAt = &finished
		record.doc.Result = &operationResultDTO{State: "cleanup_uncertain", Message: "Cleanup did not finish before the shutdown deadline. Refresh durable status before retrying."}
		h.appendEventLocked(record, "terminal", map[string]any{"state": record.doc.State, "reason": record.doc.Reason})
		h.active--
		h.counters.active.Add(-1)
		h.counters.terminal.Add(1)
		close(record.done)
		for id, subscriber := range record.subscribers {
			close(subscriber.ch)
			delete(record.subscribers, id)
			h.streams--
			h.counters.activeStreams.Add(-1)
		}
	}
}

func (h *operationHub) isDraining() bool {
	h.mu.Lock()
	defer h.mu.Unlock()
	return h.draining
}

func (h *operationHub) reapLocked() {
	now := h.now().UTC()
	for id, record := range h.records {
		if record.doc.FinishedAt != nil && now.Sub(*record.doc.FinishedAt) >= TerminalRetention {
			delete(h.records, id)
			if record.dedupKey != "" {
				delete(h.dedup, record.dedupKey)
			}
		}
	}
}

func projectOperationResult(result app.OperationResult) *operationResultDTO {
	out := &operationResultDTO{
		State: safeWebText(string(result.State)), Subject: safeWebText(result.Subject), Message: safeWebText(result.Message),
		Content: safeProjectedText(result.Content, MaxTerminalResultBytes/2), Truncated: result.Truncated,
	}
	for _, finding := range result.Findings {
		out.Findings = append(out.Findings, findingDTO{
			Severity: safeWebText(finding.Severity), Section: safeWebText(finding.Section), Problem: safeWebText(finding.Problem),
			Cause: safeWebText(finding.Cause), Suggestion: safeWebText(finding.Suggestion),
		})
	}
	if result.Error != nil {
		out.Error = &errorBody{Code: safeWebText(result.Error.Code), Message: safeWebText(result.Error.Message), Retryable: result.Error.Retryable, Details: map[string]any{
			"category": safeWebText(result.Error.Category), "component": safeWebText(result.Error.Component), "cause": safeWebText(result.Error.Cause), "guidance": safeWebText(result.Error.Guidance),
		}}
	}
	if data, _ := json.Marshal(out); len(data) > MaxTerminalResultBytes {
		out.Content = ""
		out.Findings = nil
		out.Truncated = true
		out.Message = safeBoundedText(out.Message, 4096)
	}
	return out
}

func cloneOperationDocument(doc operationDocument) operationDocument {
	clone := doc
	if doc.Result != nil {
		result := *doc.Result
		result.Findings = append([]findingDTO(nil), doc.Result.Findings...)
		if doc.Result.Error != nil {
			err := *doc.Result.Error
			result.Error = &err
		}
		clone.Result = &result
	}
	return clone
}

func terminalOperationState(state string) bool {
	switch state {
	case "succeeded", "failed", "cancelled", "interrupted", "cleanup_uncertain":
		return true
	default:
		return false
	}
}

func canonicalCancelReason(reason string) string {
	switch reason {
	case "server_shutdown", "timeout", "recovery":
		return reason
	default:
		return "user_request"
	}
}

func safeWebText(value string) string {
	return safeProjectedText(value, 4096)
}

func safeProjectedText(value string, limit int) string {
	value = strings.TrimSpace(value)
	lower := strings.ToLower(value)
	for _, marker := range []string{"token=", "secret=", "authorization:", "cookie:"} {
		if index := strings.Index(lower, marker); index >= 0 {
			value = value[:index] + "[redacted]"
			lower = strings.ToLower(value)
		}
	}
	if strings.Contains(value, "/home/") || strings.Contains(value, `C:\\Users\\`) {
		value = "[redacted path]"
	}
	return safeBoundedText(value, limit)
}

func safeBoundedText(value string, limit int) string {
	if len(value) <= limit {
		return value
	}
	return value[:limit] + "…"
}

func parseEventID(value string) (uint64, error) {
	if strings.TrimSpace(value) == "" {
		return 0, nil
	}
	id, err := strconv.ParseUint(value, 10, 64)
	if err != nil {
		return 0, fmt.Errorf("invalid Last-Event-ID")
	}
	return id, nil
}

