func (h *handler) durableOperationStatus(ctx context.Context, id string) (operationDocument, error) {
	if h.runs == nil {
		return operationDocument{}, errOperationNotFound
	}
	snapshot, err := h.runs.Run(ctx, app.RunID(id))
	if err != nil || string(snapshot.RunID) != id || snapshot.Target.Kind != "operation" {
		return operationDocument{}, errOperationNotFound
	}
	return durableOperationDocument(snapshot), nil
}

func legacyOperationID(id string) bool { return strings.HasPrefix(id, "op_") }

func durableOperationDocument(snapshot app.RunSnapshot) operationDocument {
	reason := snapshot.Cancellation.Reason
	if snapshot.Terminal != nil && snapshot.Terminal.Reason != "" {
		reason = snapshot.Terminal.Reason
	}
	return operationDocument{
		ID: string(snapshot.RunID), Kind: app.OperationKind(snapshot.Target.Operation), State: string(snapshot.Lifecycle), Reason: reason,
		CreatedAt: snapshot.AcceptedAt, StartedAt: snapshot.StartedAt, FinishedAt: snapshot.FinishedAt,
		LastEventID:   strconv.FormatUint(snapshot.LastSequence, 10),
		DurableStatus: durableStatusDTO{Available: true, RefreshPath: "/runs/" + string(snapshot.RunID)},
	}
}

func durableActiveOperation(snapshot app.RunSnapshot) activeOperationDTO {
	return activeOperationDTO{
		ID: string(snapshot.RunID), Kind: app.OperationKind(snapshot.Target.Operation), State: string(snapshot.Lifecycle),
		Project: snapshot.Target.Project, Sprint: snapshot.Target.Sprint, Study: snapshot.Target.Study, StartedAt: snapshot.StartedAt,
	}
}

// followDurableOperationEvents is the compatibility projection for a run that
// was accepted by this or another local server but is absent from this
// process's transient operation hub.
func (h *handler) followDurableOperationEvents(w http.ResponseWriter, r *http.Request, id string, after uint64) bool {
	if h.runs == nil {
		return false
	}
	snapshot, err := h.runs.Run(r.Context(), app.RunID(id))
	if err != nil || string(snapshot.RunID) != id || snapshot.Target.Kind != "operation" {
		return false
	}
	if after > snapshot.LastSequence {
		h.writeError(w, r, http.StatusConflict, "cursor_ahead", "The event cursor is ahead of the durable operation.")
		return true
	}
	if after+1 < snapshot.OldestRetainedSequence {
		h.writeError(w, r, http.StatusConflict, "replay_gap", "The requested operation history is no longer retained; refresh its canonical run.")
		return true
	}
	flusher, ok := w.(http.Flusher)
	if !ok {
		h.writeOperationError(w, r, errors.New("streaming unavailable"))
		return true
	}
	w.Header().Set("Content-Type", "text/event-stream; charset=utf-8")
	w.Header().Set("Connection", "keep-alive")
	w.Header().Set("X-Accel-Buffering", "no")
	w.WriteHeader(http.StatusOK)
	flusher.Flush()
	heartbeat := time.NewTicker(SSEHeartbeat)
	defer heartbeat.Stop()
	lifetime := time.NewTimer(MaxStreamLifetime)
	defer lifetime.Stop()
	poll := time.NewTimer(0)
	defer poll.Stop()
	for {
		select {
		case <-poll.C:
			events, eventErr := h.runs.RunEvents(r.Context(), snapshot.RunID, after, 512)
			if eventErr != nil {
				return true
			}
			for _, event := range events {
				projected := durableOperationEvent(event)
				if err := writeSSEEvent(w, projected); err != nil {
					return true
				}
				after = event.Sequence
			}
			flusher.Flush()
			snapshot, eventErr = h.runs.Run(r.Context(), snapshot.RunID)
			if eventErr != nil || snapshot.Lifecycle.IsTerminal() && after >= snapshot.LastSequence {
				return true
			}
			wait := time.Second
			if len(events) == 512 || after < snapshot.LastSequence {
				wait = 250 * time.Millisecond
			}
			poll.Reset(wait)
		case <-heartbeat.C:
			if _, err := io.WriteString(w, ": heartbeat\n\n"); err != nil {
				return true
			}
			flusher.Flush()
		case <-lifetime.C:
			return true
		case <-r.Context().Done():
			return true
		}
	}
}

func durableOperationEvent(event app.RunEvent) operationEvent {
	name := "progress"
	switch string(event.Type) {
	case "accepted", "claimed", "lifecycle":
		name = "snapshot"
	case "warning", "finding", "artifact", "terminal":
		name = string(event.Type)
	case "cancellation":
		name = "cancel_requested"
	case "recovery", "omission":
		name = "recovery_required"
	}
	payload := map[string]any{"stage": event.Stage, "task": event.Task, "payload": event.Payload, "omission": event.Omission}
	body, _ := json.Marshal(map[string]any{
		"operation_id": string(event.RunID), "time": event.CommittedAt.UTC().Format(time.RFC3339Nano),
		"sequence": event.Sequence, "payload": payload,
	})
	return operationEvent{ID: event.Sequence, Name: name, Data: body}
}

func operationSpecFromForm(r *http.Request) operationSpecRequest {
	parallelism, _ := strconv.Atoi(r.FormValue("parallelism"))
	sprintRef := r.FormValue("sprint")
	if sprintRef == "" {
		sprintRef = newSprintRef(r.FormValue("sprint_number"), r.FormValue("sprint_name"))
	}
	return operationSpecRequest{
		Kind:  r.FormValue("kind"),
		Scope: operationScopeRequest{Project: r.FormValue("project"), Sprint: sprintRef, Study: r.FormValue("study")},
		Options: operationOptionsRequest{
			ToStage:     r.FormValue("stage"),
			Task:        r.FormValue("task"),
			Shard:       r.FormValue("shard"),
			Model:       strings.TrimSpace(r.FormValue("model")),
			Suite:       strings.TrimSpace(r.FormValue("suite")),
			Parallelism: parallelism,
		},
	}
}

func newSprintRef(number, name string) string {
	number = strings.TrimSpace(number)
	name = strings.TrimSpace(name)
	if number == "" || name == "" {
		return ""
	}
	for _, r := range number {
		if r < '0' || r > '9' {
			return number + "-" + name
		}
	}
	var slug strings.Builder
	separator := false
	for _, r := range strings.ToLower(name) {
		switch {
		case r >= 'a' && r <= 'z', r >= '0' && r <= '9':
			if separator && slug.Len() > 0 {
				slug.WriteByte('-')
			}
			slug.WriteRune(r)
			separator = false
		case r == ' ' || r == '-' || r == '_':
			separator = true
		default:
			return number + "-" + name
		}
	}
	if slug.Len() == 0 {
		return ""
	}
	return number + "-" + slug.String()
}

func writeSSEEvent(w io.Writer, event operationEvent) error {
	_, err := fmt.Fprintf(w, "id: %d\nevent: %s\ndata: %s\n\n", event.ID, event.Name, event.Data)
	return err
}

func decodeStrictJSON(r *http.Request, target any) error {
	contentType := r.Header.Get("Content-Type")
	if !strings.HasPrefix(strings.ToLower(contentType), "application/json") {
		return fmt.Errorf("Content-Type must be application/json")
	}
	decoder := json.NewDecoder(r.Body)
	decoder.DisallowUnknownFields()
	if err := decoder.Decode(target); err != nil {
		return fmt.Errorf("invalid JSON request: %w", err)
	}
	var extra any
	if err := decoder.Decode(&extra); !errors.Is(err, io.EOF) {
		return fmt.Errorf("request must contain one JSON value")
	}
	return nil
}

func mapOperationRequest(spec operationSpecRequest) (app.OperationRequest, error) {
	if !validOptionalIdentifier(spec.Scope.Project) || !validOptionalIdentifier(spec.Scope.Sprint) || !validOptionalIdentifier(spec.Scope.Study) {
		return app.OperationRequest{}, fmt.Errorf("operation scope contains an invalid identifier")
	}
	options := spec.Options
	req := app.OperationRequest{
		Project: spec.Scope.Project, Sprint: spec.Scope.Sprint, Study: spec.Scope.Study,
		Stage: firstString(options.ToStage, options.Stage), Task: options.Task, Model: options.Model,
		Level: options.Level, Suite: options.Suite, Test: options.Test, Timeout: options.Timeout,
		ForceReview: options.ForceReview, RestartReview: options.RestartReview, OverrideRationale: options.OverrideRationale,
		ReviewFocus: options.ReviewFocus, Sources: options.Sources, Dimensions: options.Dimensions, Parallelism: options.Parallelism,
	}
	kind := strings.ReplaceAll(strings.TrimSpace(spec.Kind), "_", "-")
	switch kind {
	case "validation", "validate":
		req.Kind = app.OperationValidate
	case "sprint-status":
		req.Kind = app.OperationSprintStatus
	case "prompt-preview", "sprint-prompt":
		req.Kind = app.OperationPrompt
	case "dry-run", "sprint-flow-dry-run":
		req.Kind = app.OperationFlowDryRun
	case "sprint-flow":
		if options.DryRun {
			req.Kind = app.OperationFlowDryRun
		} else {
			req.Kind = app.OperationFlow
		}
	case "sprint-stage":
		if options.DryRun {
			req.Kind = app.OperationStageDryRun
		} else {
			req.Kind = app.OperationStage
		}
	case "sprint-stage-dry-run":
		req.Kind = app.OperationStageDryRun
	case "execute", "execute-start":
		switch {
		case options.Action == "status":
			req.Kind = app.OperationExecuteStatus
		case options.DryRun:
			req.Kind = app.OperationExecuteDryRun
		case options.Resume:
			req.Kind = app.OperationExecuteResume
		default:
			req.Kind = app.OperationExecuteStart
		}
	case "execute-status":
		req.Kind = app.OperationExecuteStatus
	case "execute-dry-run":
		req.Kind = app.OperationExecuteDryRun
	case "execute-resume":
		req.Kind = app.OperationExecuteResume
	case "review", "review-start":
		if options.Action == "status" {
			req.Kind = app.OperationReviewStatus
		} else if options.DryRun {
			req.Kind = app.OperationReviewDryRun
		} else {
			req.Kind = app.OperationReviewStart
		}
	case "review-status":
		req.Kind = app.OperationReviewStatus
	case "review-dry-run":
		req.Kind = app.OperationReviewDryRun
	case "smoke", "smoke-start":
		if options.Action == "status" {
			req.Kind = app.OperationSmokeStatus
		} else if options.DryRun {
			req.Kind = app.OperationSmokeDryRun
		} else {
			req.Kind = app.OperationSmokeStart
		}
	case "smoke-status":
		req.Kind = app.OperationSmokeStatus
	case "smoke-dry-run":
		req.Kind = app.OperationSmokeDryRun
	case "verify", "verify-start":
		if options.DryRun {
			req.Kind = app.OperationVerifyDryRun
		} else {
			req.Kind = app.OperationVerifyStart
		}
	case "verify-dry-run":
		req.Kind = app.OperationVerifyDryRun
	case "qa-status":
		req.Kind = app.OperationQAStatus
	case "qa-dry-run":
		req.Kind = app.OperationQADryRun
	case "qa-start":
		req.Kind = app.OperationQAStart
		req.Task = options.Shard
	case "qa-resume":
		req.Kind = app.OperationQAResume
		req.Task = options.Shard
	case "qa-recover":
		req.Kind = app.OperationQARecover
	case "study-run-loop", "study-start":
		if options.Resume {
			req.Kind = app.OperationStudyResume
		} else {
			req.Kind = app.OperationStudyStart
		}
	case "study-resume":
		req.Kind = app.OperationStudyResume
	case "study-cancel":
		req.Kind = app.OperationStudyCancel
	default:
		return app.OperationRequest{}, fmt.Errorf("unsupported operation kind %q", spec.Kind)
	}
	if req.Kind == app.OperationValidate {
		if (req.Project == "") == (req.Study == "") {
			return app.OperationRequest{}, fmt.Errorf("validation requires one project or study scope")
		}
	} else if strings.HasPrefix(string(req.Kind), "study-") {
		if req.Study == "" || req.Project != "" || req.Sprint != "" {
			return app.OperationRequest{}, fmt.Errorf("study operations require only scope.study")
		}
	} else if req.Project == "" {
		return app.OperationRequest{}, fmt.Errorf("project operations require scope.project")
	} else if req.Sprint == "" {
		return app.OperationRequest{}, fmt.Errorf("sprint operations require scope.sprint")
	}
	if strings.HasPrefix(string(req.Kind), "qa-") {
		if options.Task != "" || options.Model != "" || options.Stage != "" || options.ToStage != "" || options.Action != "" || options.DryRun || options.Resume || options.Level != "" || options.Test != "" || options.Timeout != "" || options.ForceReview || options.RestartReview || options.OverrideRationale != "" || len(options.ReviewFocus) > 0 || len(options.Sources) > 0 || len(options.Dimensions) > 0 || options.Parallelism != 0 {
			return app.OperationRequest{}, fmt.Errorf("QA operations accept only options.shard or options.suite")
		}
		if options.Suite != "" && options.Suite != "smoke" {
			return app.OperationRequest{}, fmt.Errorf("QA options.suite must be smoke")
		}
		if options.Suite != "" && req.Kind != app.OperationQAStart && req.Kind != app.OperationQADryRun {
			return app.OperationRequest{}, fmt.Errorf("QA suite is valid only for start or dry-run")
		}
		if options.Suite != "" && options.Shard != "" {
			return app.OperationRequest{}, fmt.Errorf("QA suite and shard are mutually exclusive")
		}
		req.Suite = options.Suite
		if options.Shard != "" && req.Kind != app.OperationQAStart && req.Kind != app.OperationQAResume {
			return app.OperationRequest{}, fmt.Errorf("QA shard is valid only for start or resume")
		}
	}
	return req, nil
}

func mapOperationSpec(req app.OperationRequest) map[string]any {
	scope := map[string]any{}
	if req.Project != "" {
		scope["project"] = req.Project
	}
	if req.Sprint != "" {
		scope["sprint"] = req.Sprint
	}
	if req.Study != "" {
		scope["study"] = req.Study
	}
	options := map[string]any{}
	if req.Stage != "" {
		options["stage"] = req.Stage
	}
	if req.Task != "" {
		if req.Kind == app.OperationQAStart || req.Kind == app.OperationQAResume {
			options["shard"] = req.Task
		} else {
			options["task"] = req.Task
		}
	}
	if req.Model != "" {
		options["model"] = req.Model
	}
	if req.Parallelism > 0 {
		options["parallelism"] = req.Parallelism
	}
	if req.Suite != "" {
		options["suite"] = req.Suite
	}
	return map[string]any{"kind": req.Kind, "scope": scope, "options": options}
}

func validOptionalIdentifier(value string) bool {
	return value == "" || validIdentifier(value)
}

func firstString(values ...string) string {
	for _, value := range values {
		if strings.TrimSpace(value) != "" {
			return strings.TrimSpace(value)
		}
	}
	return ""
}

func (h *handler) writeOperationError(w http.ResponseWriter, r *http.Request, err error) {
	status, code, message, retryable := http.StatusBadRequest, "invalid_request", "The operation request is invalid.", false
	details := map[string]any{}
	switch {
	case errors.Is(err, errConfirmationExpired):
		status, code, message, retryable = http.StatusConflict, "confirmation_expired", "The confirmation expired. Prepare the operation again.", true
	case errors.Is(err, errConfirmationMismatch):
		status, code, message = http.StatusConflict, "confirmation_mismatch", "The confirmation does not match this session or operation."
	case errors.Is(err, errConfirmationReplayed):
		status, code, message = http.StatusConflict, "confirmation_replayed", "The confirmation was already used or is unknown."
	case errors.Is(err, errStaleConfirmation), errors.Is(err, app.ErrStaleOperation):
		status, code, message, retryable = http.StatusConflict, "stale_confirmation", "The operation inputs changed after confirmation. Prepare it again.", true
	case errors.Is(err, errOperationNotFound):
		status, code, message = http.StatusNotFound, "operation_not_found", "The operation is no longer retained. Refresh durable status."
		details["action"] = "refresh_durable_status"
	case errors.Is(err, errOperationCapacity):
		status, code, message, retryable = http.StatusTooManyRequests, "operation_capacity", "Operation capacity is currently full.", true
		w.Header().Set("Retry-After", "2")
	case errors.Is(err, errSubscriberCapacity):
		status, code, message, retryable = http.StatusTooManyRequests, "subscriber_capacity", "Stream capacity is currently full.", true
		w.Header().Set("Retry-After", "2")
	case errors.Is(err, errServerDraining):
		status, code, message, retryable = http.StatusServiceUnavailable, "server_draining", "The server is shutting down and is not accepting new work.", true
		w.Header().Set("Retry-After", "2")
	case errors.Is(err, context.Canceled), errors.Is(err, context.DeadlineExceeded):
		status, code, message, retryable = http.StatusServiceUnavailable, "server_draining", "The server is shutting down.", true
	case strings.Contains(strings.ToLower(err.Error()), "validation"), strings.Contains(strings.ToLower(err.Error()), "incomplete"), strings.Contains(strings.ToLower(err.Error()), "prerequisite"):
		status, code, message = http.StatusUnprocessableEntity, "validation_failed", "The governed inputs failed validation."
	case strings.Contains(strings.ToLower(err.Error()), "lock"), strings.Contains(strings.ToLower(err.Error()), "in progress"):
		status, code, message, retryable = http.StatusConflict, "operation_conflict", "A conflicting operation is already running.", true
	case strings.Contains(strings.ToLower(err.Error()), "unavailable"):
		status, code, message, retryable = http.StatusFailedDependency, "prerequisite_unavailable", "A required operation prerequisite is unavailable.", true
	case !isClientOperationError(err):
		status, code, message = http.StatusInternalServerError, "internal_failure", "The operation could not be completed."
	}
	if cause := safeOperationCause(err); cause != "" && status < http.StatusInternalServerError {
		details["reason"] = cause
		details["guidance"] = operationFailureGuidance(code)
	}
	h.writeErrorDetails(w, r, status, errorBody{Code: code, Message: message, Retryable: retryable, Details: details})
}

func safeOperationCause(err error) string {
	if err == nil {
		return ""
	}
	text := strings.ToLower(err.Error())
	if isClientOperationError(err) || strings.Contains(text, "validation") || strings.Contains(text, "incomplete") || strings.Contains(text, "prerequisite") || strings.Contains(text, "lock") || strings.Contains(text, "in progress") || strings.Contains(text, "unavailable") {
		return safeWebText(err.Error())
	}
	return ""
}

func operationFailureGuidance(code string) string {
	switch code {
	case "validation_failed":
		return "Open the sprint Plan and Delivery pages, correct the reported incomplete or invalid evidence, then retry."
	case "operation_conflict":
		return "Wait for the active operation to finish or inspect and cancel it before retrying."
	case "prerequisite_unavailable":
		return "Restore the missing prerequisite or runtime capability, then prepare the operation again."
	default:
		return "Correct the reported reason and prepare the operation again."
	}
}

func htmlOperationFailure(summary string, err error) string {
	cause := safeOperationCause(err)
	if cause == "" {
		return summary
	}
	return summary + " Reason: " + cause + " Correct the reported prerequisite or governed artifact, then retry."
}

func isClientOperationError(err error) bool {
	text := strings.ToLower(err.Error())
	return strings.Contains(text, "required") || strings.Contains(text, "invalid") || strings.Contains(text, "unsupported") || strings.Contains(text, "json") || strings.Contains(text, "content-type") || strings.Contains(text, "scope")
}

func (h *handler) writeErrorDetails(w http.ResponseWriter, r *http.Request, status int, body errorBody) {
	meta := responseMeta{APIVersion: "v1", RequestID: requestID(r.Context()), GeneratedAt: h.now().UTC().Format(time.RFC3339Nano)}
	writeJSON(w, status, errorEnvelope{Error: body, Meta: meta})
}

func eventIDHeader(value string) string {
	if value == "" {
		return "0"
	}
	if _, err := strconv.ParseUint(value, 10, 64); err != nil {
		return "0"
	}
	return value
}

func (h *handler) logOperation(r *http.Request, event, operationID, kind, state, reason string) {
	fmt.Fprintf(h.diagnostics,
		"event=%s request_id=%s operation_id=%s kind=%s state=%s reason=%s\n",
		safeWebText(event), safeWebText(requestID(r.Context())), safeWebText(operationID), safeWebText(kind), safeWebText(state), safeWebText(reason))
}

package tui

import (
	"context"
	"crypto/sha256"
	"encoding/hex"
	"errors"
	"fmt"
	"io"
	"strconv"
	"time"

	"github.com/Antonio7098/ultraplan-go/internal/app"
	tea "github.com/charmbracelet/bubbletea"
)

type Options struct {
	UseCases app.OperationalUseCases
	Stdout   io.Writer
	Width    int
}

func Run(ctx context.Context, opts Options) error {
	if opts.UseCases == nil {
		return fmt.Errorf("tui: missing read-only use cases")
	}
	if opts.Stdout == nil {
		opts.Stdout = io.Discard
	}
	program := tea.NewProgram(newTeaModel(ctx, opts.UseCases, opts.Width), tea.WithAltScreen(), tea.WithOutput(opts.Stdout))
	_, err := program.Run()
	return err
}

type teaModel struct {
	ctx         context.Context
	model       Model
	width       int
	height      int
	cancel      context.CancelFunc
	eventStream <-chan app.OperationEvent
}
type runViewTickMsg struct{}

func newTeaModel(ctx context.Context, useCases app.OperationalUseCases, width int) teaModel {
	if width <= 0 {
		width = 100
	}
	return teaModel{ctx: ctx, model: NewModel(useCases), width: width, height: 40}
}

func (m teaModel) Init() tea.Cmd {
	return m.loadCmd()
}

func (m teaModel) Update(msg tea.Msg) (tea.Model, tea.Cmd) {
	switch v := msg.(type) {
	case tea.WindowSizeMsg:
		m.width = v.Width
		m.height = v.Height
		return m, nil
	case tea.KeyMsg:
		if m.model.ParallelForm != nil {
			switch v.String() {
			case "esc":
				m.model.ParallelForm = nil
				m.model.ParallelValue = ""
				m.model.ParallelError = ""
				return m, nil
			case "backspace":
				if len(m.model.ParallelValue) > 0 {
					m.model.ParallelValue = m.model.ParallelValue[:len(m.model.ParallelValue)-1]
				}
				m.model.ParallelError = ""
				return m, nil
			case "enter":
				value := 3
				if m.model.ParallelValue != "" {
					parsed, err := strconv.Atoi(m.model.ParallelValue)
					if err != nil || parsed < 1 || parsed > 64 {
						m.model.ParallelError = "parallelism must be between 1 and 64"
						return m, nil
					}
					value = parsed
				}
				req := *m.model.ParallelForm
				req.Parallelism = value
				m.model.ParallelForm = nil
				m.model.ParallelValue = ""
				m.model.Loading = true
				return m, m.confirmationCmd(req)
			default:
				if len(v.Runes) == 1 && v.Runes[0] >= '0' && v.Runes[0] <= '9' {
					m.model.ParallelValue += string(v.Runes[0])
					m.model.ParallelError = ""
				}
				return m, nil
			}
		}
		action := KeyToAction(v.String())
		switch action {
		case ActionConfirm:
			if m.model.Confirmation != nil && !m.model.Running {
				return m.beginOperation(m.model.Confirmation.Request)
			}
			return m, nil
		case ActionCancel:
			if m.model.Running && m.model.ActiveRunID != "" {
				if runs, ok := m.model.UseCases.(app.RunUseCases); ok {
					if _, _, err := runs.CancelRun(m.ctx, app.RunID(m.model.ActiveRunID), "user_requested"); err != nil {
						m.model.Error = err.Error()
					} else if m.model.Operation != nil {
						m.model.Operation.Message = "durable cancellation requested; waiting for owner acknowledgement"
					}
					return m, nil
				}
			}
			if m.model.Running && m.cancel != nil {
				m.cancel()
				return m, nil
			}
			if route := m.model.currentRoute(); route.Kind == RouteRun && route.RunID != "" {
				if runs, ok := m.model.UseCases.(app.RunUseCases); ok {
					if _, _, err := runs.CancelRun(m.ctx, app.RunID(route.RunID), "user_requested"); err != nil {
						m.model.Error = err.Error()
					} else {
						m.model.Error = "durable cancellation requested"
					}
					return m, m.refreshCmd()
				}
			}
			study := m.model.RunViewStudy
			if study == "" {
				if item, ok := m.model.selectedItem(); ok {
					study = item.ViewRun
				}
			}
			if study != "" && !m.model.Running {
				return m.beginOperation(app.OperationRequest{Kind: app.OperationStudyCancel, Study: study})
			}
			return m, nil
		case ActionQuit:
			if m.model.Running {
				m.model.OperationHidden = true
				m.model.Error = "active durable work was not cancelled; press c to request cancellation or reopen its run"
				return m, nil
			}
			m.model = m.model.Update(KeyMsg(v.String()))
			return m, tea.Quit
		case ActionRefresh:
			m.model.Loading = true
			return m, m.refreshCmd()
		case ActionOpen:
			if m.model.Confirmation != nil && !m.model.Running {
				return m.beginOperation(m.model.Confirmation.Request)
			}
			if m.model.RunViewStudy != "" {
				m.model.RunViewShowPrevious = !m.model.RunViewShowPrevious
				return m, nil
			}
			if m.model.Running && !m.model.OperationHidden && (m.model.ActiveOperation.Kind == app.OperationStudyStart || m.model.ActiveOperation.Kind == app.OperationStudyResume) {
				m.model.OperationShowPrevious = !m.model.OperationShowPrevious
				return m, nil
			}
			if item, ok := m.model.selectedItem(); ok && item.ViewRun != "" && m.model.Focus == FocusContent {
				m.model.RunViewStudy = item.ViewRun
				m.model.RunViewShowPrevious = false
				return m, tea.Batch(m.refreshCmd(), runViewTickCmd())
			}
			if item, ok := m.model.selectedItem(); ok && item.Validation != nil && m.model.Focus == FocusContent && m.model.Preview == nil {
				m.model.Loading = true
				return m, m.validationCmd(*item.Validation)
			}
			if item, ok := m.model.selectedItem(); ok && item.Operation != nil && m.model.Focus == FocusContent {
				if item.Operation.Kind == app.OperationStudyResume || item.Operation.Kind == app.OperationStudyStart {
					req := *item.Operation
					m.model.ParallelForm = &req
					m.model.ParallelValue = ""
					m.model.ParallelError = ""
					return m, nil
				}
				m.model.Loading = true
				return m, m.confirmationCmd(*item.Operation)
			}
			if item, ok := m.model.selectedItem(); ok && item.Path != "" && m.model.Focus == FocusContent && m.model.Preview == nil {
				return m, m.previewCmd()
			}
			m.model = m.model.Update(KeyMsg(v.String()))
			if m.model.currentRoute().Kind == RouteRun {
				return m, tea.Batch(m.refreshCmd(), runViewTickCmd())
			}
			return m, nil
		case ActionBack, ActionFocusNext, ActionLeft, ActionRight:
			if action == ActionBack && m.model.Running && !m.model.OperationHidden && (m.model.ActiveOperation.Kind == app.OperationStudyStart || m.model.ActiveOperation.Kind == app.OperationStudyResume) {
				m.model.OperationHidden = true
				m.model.OperationShowPrevious = false
				return m, m.refreshCmd()
			}
			m.model = m.model.Update(KeyMsg(v.String()))
			return m, nil
		case ActionClosePreview:
			m.model = m.model.Update(KeyMsg(v.String()))
			return m, nil
		default:
			m.model = m.model.Update(KeyMsg(v.String()))
			return m, nil
		}
	case OperationMsg:
		m.model = m.model.Update(v)
		m.cancel = nil
		m.eventStream = nil
		return m, m.refreshCmd()
	case OperationEventMsg:
		m.model = m.model.Update(v)
		if m.eventStream != nil && m.model.Running {
			return m, waitOperationEvent(m.eventStream)
		}
		return m, nil
	case LoadMsg, RefreshMsg, PreviewMsg, ValidationMsg, ConfirmationMsg:
		m.model = m.model.Update(v)
		return m, nil
	case runViewTickMsg:
		if m.model.RunViewStudy != "" || m.model.currentRoute().Kind == RouteRun {
			return m, tea.Batch(m.refreshCmd(), runViewTickCmd())
		}
		return m, nil
	default:
		return m, nil
	}
}

func (m teaModel) beginOperation(req app.OperationRequest) (tea.Model, tea.Cmd) {
	opctx, cancel := context.WithCancel(m.ctx)
	acceptedRunID := ""
	if manager, ok := m.model.UseCases.(app.DurableOperationManager); ok && m.model.Confirmation != nil {
		basis := m.model.Confirmation.CanonicalRequest + "\x00" + m.model.Confirmation.InputFingerprint
		digest := sha256.Sum256([]byte(basis))
		accepted, err := manager.AcceptOperation(opctx, *m.model.Confirmation, hex.EncodeToString(digest[:]))
		if err != nil {
			cancel()
			m.model.Error = err.Error()
			m.model.Loading = false
			return m, nil
		}
		if accepted.Existing {
			cancel()
			m.model.Operation = &app.OperationResult{State: app.OperationState(accepted.Lifecycle), RunID: accepted.RunID, Message: "matching durable operation already exists"}
			m.model.Confirmation = nil
			return m, nil
		}
		acceptedRunID = accepted.RunID
		if accepted.Context != nil {
			opctx = accepted.Context
		}
	}
	m.cancel = cancel
	m.model.Running = true
	m.model.Events = nil
	m.model.Confirmation = nil
	m.model.RunViewStudy = ""
	m.model.ActiveOperation = req
	m.model.OperationShowPrevious = false
	m.model.OperationHidden = false
	m.model.ActiveRunID = acceptedRunID
	m.model.Operation = &app.OperationResult{State: app.OperationRunning, RunID: acceptedRunID, Subject: operationSubject(req), Message: "operation running; c requests durable cancellation; q keeps the run active"}
	stream := make(chan app.OperationEvent, 128)
	m.eventStream = stream
	return m, tea.Batch(m.operationCmd(opctx, req, acceptedRunID, stream), waitOperationEvent(stream))
}

func runViewTickCmd() tea.Cmd {
	return tea.Tick(time.Second, func(time.Time) tea.Msg { return runViewTickMsg{} })
}

func (m teaModel) confirmationCmd(req app.OperationRequest) tea.Cmd {
	route := m.model.currentRoute()
	return func() tea.Msg {
		r, e := m.model.UseCases.PrepareOperation(m.ctx, req)
		return ConfirmationMsg{Result: r, Err: e, Route: route}
	}
}
func (m teaModel) operationCmd(ctx context.Context, req app.OperationRequest, runID string, stream chan app.OperationEvent) tea.Cmd {
	route := m.model.currentRoute()
	return func() tea.Msg {
		defer close(stream)
		r, e := m.model.UseCases.RunOperation(ctx, req, func(event app.OperationEvent) {
			if manager, ok := m.model.UseCases.(app.DurableOperationManager); ok && runID != "" {
				committed, err := manager.RecordOperationEvent(context.Background(), runID, event)
				if err != nil && !errors.Is(err, app.ErrWebUnavailable) {
					return
				}
				if err == nil && !committed {
					return
				}
			}
			select {
			case stream <- event:
			default:
			}
		})
		r.RunID = runID
		if manager, ok := m.model.UseCases.(app.DurableOperationManager); ok && runID != "" {
			finishCtx, cancel := context.WithTimeout(context.Background(), 30*time.Second)
			finishErr := manager.FinishOperation(finishCtx, runID, r.State, e)
			cancel()
			if finishErr != nil {
				e = errors.Join(e, finishErr)
			}
		}
		return OperationMsg{Result: r, Err: e, Route: route}
	}
}

func waitOperationEvent(stream <-chan app.OperationEvent) tea.Cmd {
	return func() tea.Msg {
		event, ok := <-stream
		if !ok {
			return nil
		}
		return OperationEventMsg{Event: event}
	}
}

func operationSubject(req app.OperationRequest) string {
	if req.Study != "" {
		return req.Study
	}
	return req.Project + "/" + req.Sprint
}

func (m teaModel) validationCmd(req app.ValidationRequest) tea.Cmd {
	route := m.model.currentRoute()
	return func() tea.Msg {
		result, err := m.model.UseCases.Validate(m.ctx, req)
		return ValidationMsg{Result: result, Err: err, Route: route}
	}
}

func (m teaModel) View() string {
	return RenderWithSize(m.model, m.width, m.height)
}

func (m teaModel) loadCmd() tea.Cmd {
	return func() tea.Msg {
		result, runs, events, err := m.dashboardAndRuns()
		return LoadMsg{Result: result, Runs: runs, Events: events, Err: err}
	}
}

func (m teaModel) refreshCmd() tea.Cmd {
	return func() tea.Msg {
		result, runs, events, err := m.dashboardAndRuns()
		return RefreshMsg{Result: result, Runs: runs, Events: events, Err: err}
	}
}

func (m teaModel) dashboardAndRuns() (app.DashboardResult, []app.RunSnapshot, []app.RunEvent, error) {
	result, err := m.model.UseCases.Dashboard(m.ctx)
	if err != nil {
		return result, nil, nil, err
	}
	runsCapability, ok := m.model.UseCases.(app.RunUseCases)
	if !ok {
		return result, nil, nil, nil
	}
	page, err := runsCapability.Runs(m.ctx, app.RunQuery{Limit: 200})
	if err != nil && !errors.Is(err, app.ErrWebUnavailable) {
		return result, nil, nil, err
	}
	var events []app.RunEvent
	route := m.model.currentRoute()
	if route.Kind == RouteRun && route.RunID != "" {
		for _, snapshot := range page.Runs {
			if string(snapshot.RunID) != route.RunID {
				continue
			}
			after := uint64(0)
			if snapshot.OldestRetainedSequence > 1 {
				after = snapshot.OldestRetainedSequence - 1
			}
			events, err = runsCapability.RunEvents(m.ctx, snapshot.RunID, after, 200)
			if err != nil {
				return result, page.Runs, nil, err
			}
			break
		}
	}
	return result, page.Runs, events, nil
}

func (m teaModel) previewCmd() tea.Cmd {
	return func() tea.Msg {
		item, ok := m.model.selectedItem()
		if !ok || item.Path == "" {
			return PreviewMsg{Result: app.ArtifactPreviewResult{Error: "no previewable artifact selected"}, Route: m.model.currentRoute(), Title: "Preview"}
		}
		result, err := m.model.UseCases.PreviewArtifact(m.ctx, item.Path)
		return PreviewMsg{Result: result, Err: err, Route: m.model.currentRoute(), Title: item.Label}
	}
}

package app

import (
	"context"
	"fmt"
	"strings"
	"time"

	"github.com/Antonio7098/ultraplan-go/internal/platform/config"
	"github.com/Antonio7098/ultraplan-go/internal/sprint"
	"github.com/Antonio7098/ultraplan-go/internal/study"
	"github.com/Antonio7098/ultraplan-go/internal/workspace"
)

// sharedOperationRunner is the single runtime-backed implementation used by
// terminal and browser adapters. Surface code owns presentation and
// confirmation; workflow semantics remain here and in the product services.
func sharedOperationRunner(deps dependencies, root workspace.Root, effective config.Effective, useCases dashboardUseCases) func(context.Context, OperationRequest, func(OperationEvent)) (OperationResult, error) {
	return func(ctx context.Context, req OperationRequest, emit func(OperationEvent)) (OperationResult, error) {
		result := OperationResult{State: OperationComplete, Subject: operationFirstNonEmpty(req.Project+"/"+req.Sprint, req.Study)}
		switch req.Kind {
		case OperationStage:
			service, e := sprintRuntimeService(deps, root, tuiSprintRuntimeProgress(emit))
			if e != nil {
				return failedOperation(result, e)
			}
			r, e := service.FlowStage(ctx, req.Project, req.Sprint, stageFlowRequest(req, func(progress sprint.FlowProgress) {
				summary := displaySafe(progress.Message)
				emit(OperationEvent{State: OperationRunning, Stage: string(progress.Stage), Message: progress.State + ": " + summary, PhaseState: progress.State, SafeSummary: summary})
			}))
			result.Message = r.Message
			result = operationWithSprintFindings(result, r.Findings)
			if e != nil {
				return failedOperation(result, e)
			}
		case OperationFlow:
			service, e := sprintRuntimeService(deps, root, tuiSprintRuntimeProgress(emit))
			if e != nil {
				return failedOperation(result, e)
			}
			flow := stageFlowRequest(req, func(progress sprint.FlowProgress) {
				summary := displaySafe(progress.Message)
				emit(OperationEvent{State: OperationRunning, Stage: string(progress.Stage), Message: progress.State + ": " + summary, PhaseState: progress.State, SafeSummary: summary})
			})
			flow.Review = sprint.ReviewRequest{Restart: req.RestartReview}
			flow.Smoke = sprint.SmokeRequest{NonInteractive: true, OverrideConfirmed: req.ForceReview, ForceReview: req.ForceReview, OverrideRationale: req.OverrideRationale}
			r, e := runSprintFlow(ctx, service, req.Project, req.Sprint, flow)
			result.Message = r.Message
			result = operationWithSprintFindings(result, r.Findings)
			if e != nil {
				return failedOperation(result, e)
			}
		case OperationExecuteStart, OperationExecuteResume:
			service, e := sprintRuntimeService(deps, root, tuiSprintRuntimeProgress(emit))
			if e != nil {
				return failedOperation(result, e)
			}
			r, e := service.Execute(ctx, req.Project, req.Sprint, sprint.ExecuteRequest{TaskID: req.Task, ModelOverride: req.Model, Resume: req.Kind == OperationExecuteResume})
			result.Message = r.Message
			result = operationWithSprintFindings(result, r.Findings)
			if e != nil {
				return failedOperation(result, e)
			}
		case OperationReviewStart:
			service, e := sprintRuntimeService(deps, root, tuiSprintRuntimeProgress(emit))
			if e != nil {
				return failedOperation(result, e)
			}
			r, e := service.Review(ctx, req.Project, req.Sprint, sprint.ReviewRequest{Concurrency: req.Parallelism, Focus: req.ReviewFocus, Restart: req.RestartReview, ModelOverride: req.Model, Progress: func(p sprint.ReviewProgress) {
				emit(OperationEvent{State: OperationRunning, Stage: "review", Task: p.CoverageID, Message: p.Message, Completed: p.Completed, Total: p.Total})
			}})
			result.Message = fmt.Sprintf("%s verdict=%s", r.Status, r.Verdict)
			for _, f := range r.Findings {
				result.Findings = append(result.Findings, DisplayFinding{Severity: f.Severity, Section: "review", Problem: f.Title, Cause: f.Detail, Suggestion: f.Action})
			}
			if e != nil {
				return failedOperation(result, e)
			}
		case OperationSmokeStart:
			service := sprint.NewService(root.Path).WithPublisher(stagePublisher(effective.Config)).WithSmokeSettings(smokeSettings(effective, envLookup(deps.env)))
			var timeout time.Duration
			if req.Timeout != "" {
				timeout, _ = time.ParseDuration(req.Timeout)
			}
			r, e := service.RunSmoke(ctx, req.Project, req.Sprint, sprint.SmokeRequest{Level: req.Level, Suite: req.Suite, Test: req.Test, Timeout: timeout, ForceReview: req.ForceReview, OverrideConfirmed: req.ForceReview, OverrideRationale: req.OverrideRationale, Progress: func(p sprint.SmokeProgress) {
				emit(OperationEvent{State: OperationRunning, Stage: string(p.Phase), Task: operationFirstNonEmpty(p.Test, p.Suite), Message: p.Message, Completed: p.Completed, Total: p.Total})
			}})
			result.Message = fmt.Sprintf("%s verdict=%s run=%s next=%s", r.Status, r.Verdict, r.RunID, r.NextAction)
			if r.Artifact != "" {
				if preview, readErr := useCases.PreviewArtifact(ctx, r.Artifact); readErr == nil {
					result.Content, result.Truncated = boundContent(preview.Content)
				}
			}
			if e != nil {
				return failedOperation(result, e)
			}
		case OperationVerifyStart:
			service, e := sprintRuntimeService(deps, root, tuiSprintRuntimeProgress(emit))
			if e != nil {
				return failedOperation(result, e)
			}
			var timeout time.Duration
			if req.Timeout != "" {
				timeout, _ = time.ParseDuration(req.Timeout)
			}
			r, e := service.Verify(ctx, req.Project, req.Sprint, sprint.VerifyRequest{To: sprint.PlanningStage(req.Stage), Review: sprint.ReviewRequest{Focus: req.ReviewFocus, Restart: req.RestartReview}, Smoke: sprint.SmokeRequest{Level: req.Level, Suite: req.Suite, Test: req.Test, Timeout: timeout, ForceReview: req.ForceReview, OverrideConfirmed: req.ForceReview, OverrideRationale: req.OverrideRationale}, Progress: func(p sprint.FlowProgress) {
				summary := displaySafe(p.Message)
				emit(OperationEvent{State: OperationRunning, Stage: string(p.Stage), Message: p.State + ": " + summary, PhaseState: p.State, SafeSummary: summary})
			}})
			result.Message = fmt.Sprintf("assessment=%s next=%s", r.Verification.Assessment, r.Verification.NextAction)
			if e != nil {
				return failedOperation(result, e)
			}
		case OperationQAStart, OperationQAResume:
			token, fence, e := qaOwnershipFromContext(ctx)
			if e != nil {
				return failedOperation(result, e)
			}
			service, e := sprintRuntimeService(deps, root, tuiSprintRuntimeProgress(emit))
			if e != nil {
				return failedOperation(result, e)
			}
			service = service.WithQAWriterFence(fence)
			r, e := service.RunQA(ctx, req.Project, req.Sprint, sprint.QARunRequest{Resume: req.Kind == OperationQAResume, FocusShard: req.Task, Suite: req.Suite, EvidenceProducing: req.Suite == "", WriterToken: token, Progress: func(progress sprint.QAProgress) {
				emit(OperationEvent{State: OperationRunning, Stage: string(progress.Phase), Task: progress.ShardID, Message: progress.Message, Action: progress.Event, Reason: string(progress.ShardPhase), Detail: string(progress.ShardKind), Completed: progress.Completed, Total: progress.Total})
			}})
			result.Message = fmt.Sprintf("phase=%s shards=%d/%d next=%s", r.State.Phase, r.State.CompletedShards, r.State.TotalShards, r.State.NextAction)
			if e != nil {
				return failedOperation(result, e)
			}
		case OperationStudyStart, OperationStudyResume:
			flags := runAllFlags{}
			flags.parallelism = &req.Parallelism
			flags.model = req.Model
			service, parallel, summary, e := runLoopService(deps, root, flags)
			if e != nil {
				return failedOperation(result, e)
			}
			r, e := service.RunLoop(ctx, study.RunLoopRequest{StudyRef: req.Study, DimensionRefs: req.Dimensions, SourceRefs: req.Sources, Parallelism: parallel, Model: studyModelOverride(deps, flags.model), Config: summary, Continue: req.Kind == OperationStudyResume, Command: []string{"ultraplan", "operation"}, Progress: func(p study.RunLoopProgress) {
				stats := operationTaskStats(p.Task, time.Now().UTC())
				event := OperationEvent{State: OperationRunning, Task: p.Task.ID, Stage: string(p.Event), Message: strings.TrimSpace(p.Task.DimensionRef + " " + p.Task.Source), Completed: p.ScopeCounts.Completed, Total: p.ScopeCounts.Total, Attempt: p.Task.Attempts, RuntimeAttempts: stats.RuntimeAttempts, Turns: stats.Turns, TurnsKnown: stats.TurnsKnown, Tokens: stats.Tokens, TokensKnown: stats.TokensKnown, InputTokens: stats.InputTokens, OutputTokens: stats.OutputTokens, ReasoningTokens: stats.ReasoningTokens, CacheReadTokens: stats.CacheReadTokens, CacheWriteTokens: stats.CacheWriteTokens, Duration: stats.Duration, Provider: stats.Provider, Model: stats.Model, Harness: stats.Runtime, Cost: stats.Cost, RuntimeEvents: stats.Events}
				if p.RuntimeEvent != nil {
					applyRuntimeObservation(&event, *p.RuntimeEvent)
					event.Message = runtimeProgressSummary(*p.RuntimeEvent)
				}
				emit(event)
			}})
			result.Message = string(r.Status)
			if e != nil {
				return failedOperation(result, e)
			}
		case OperationStudyCancel:
			service := study.NewService(root.Path)
			listing, e := service.ListStudy(req.Study)
			if e != nil {
				return failedOperation(result, e)
			}
			info, e := study.CancelRunLoop(listing.Study)
			if e != nil {
				return failedOperation(result, e)
			}
			result.Message = fmt.Sprintf("cancellation requested from run-loop process %d", info.PID)
		default:
			return failedOperation(result, fmt.Errorf("unsupported runtime operation %q", req.Kind))
		}
		emit(OperationEvent{State: OperationComplete, Message: "operation complete"})
		return result, nil
	}
}

// stageFlowRequest builds the sprint flow request for a stage or flow
// operation. A requested model applies to the selected target stage and, as a
// fallback for stages without dedicated per-stage handling (code-context), as
// the generic model override. Empty models keep configured defaults.
func stageFlowRequest(req OperationRequest, progress func(sprint.FlowProgress)) sprint.FlowRequest {
	flow := sprint.FlowRequest{To: sprint.PlanningStage(req.Stage), ModelOverride: req.Model}
	if req.Model != "" && req.Stage != "" {
		stage := sprint.PlanningStage(req.Stage)
		if _, ok := flow.StageOverrides[stage]; !ok {
			flow.StageOverrides = map[sprint.PlanningStage]sprint.StageRuntime{}
		}
		override := flow.StageOverrides[stage]
		override.Model = req.Model
		flow.StageOverrides[stage] = override
	}
	flow.Progress = progress
	return flow
}

