package app

import (
	"context"
	"encoding/json"
	"errors"
	"fmt"
	"sort"
	"strings"
	"sync"
	"time"

	"github.com/Antonio7098/ultraplan-go/internal/platform/config"
	runtimepkg "github.com/Antonio7098/ultraplan-go/internal/platform/runtime"
	"github.com/Antonio7098/ultraplan-go/internal/runcontrol"
)

const runControlLease = runcontrol.OwnerLeaseDuration

// runControlState owns one repository handle per workspace for the lifetime of
// the process. dependencies is copied throughout command dispatch, so keeping
// this state behind a pointer prevents accidental duplicate connection pools.
type runControlState struct {
	mu       sync.Mutex
	repos    map[string]*runcontrol.SQLiteRepository
	loggers  map[string]*runcontrol.LocalFileLogger
	policies map[string]runcontrol.RetentionPolicy
	owner    runcontrol.Owner
	initErr  error
}

func newRunControlState() *runControlState {
	owner, err := currentRunOwner()
	return &runControlState{repos: make(map[string]*runcontrol.SQLiteRepository), loggers: make(map[string]*runcontrol.LocalFileLogger), policies: make(map[string]runcontrol.RetentionPolicy), owner: owner, initErr: err}
}

func (s *runControlState) repository(ctx context.Context, workspaceRoot string, policies ...runcontrol.RetentionPolicy) (*runcontrol.SQLiteRepository, error) {
	if s == nil {
		return nil, errors.New("run-control process state is unavailable")
	}
	s.mu.Lock()
	defer s.mu.Unlock()
	if s.initErr != nil {
		return nil, s.initErr
	}
	if repository := s.repos[workspaceRoot]; repository != nil {
		if len(policies) > 0 && s.policies[workspaceRoot] != policies[0] {
			return nil, errors.New("run-control retention policy changed during the process lifetime")
		}
		return repository, nil
	}
	var retention runcontrol.RetentionPolicy
	if len(policies) > 0 {
		retention = policies[0]
	}
	repository, err := runcontrol.OpenSQLite(ctx, workspaceRoot, runcontrol.SQLiteOptions{Retention: retention})
	if err != nil {
		return nil, err
	}
	logger, err := runcontrol.OpenLocalFileLogger(workspaceRoot)
	if err != nil {
		_ = repository.Close()
		return nil, fmt.Errorf("open run-control diagnostic log: %w", err)
	}
	repository.SetLogger(logger)
	if _, err := repository.Reconcile(ctx, runcontrol.NativeProcessProbe{}, runcontrol.ReconcileOptions{}); err != nil {
		_ = repository.Close()
		_ = logger.Close()
		return nil, fmt.Errorf("startup run reconciliation failed: %w", err)
	}
	s.repos[workspaceRoot] = repository
	s.loggers[workspaceRoot] = logger
	s.policies[workspaceRoot] = retention
	return repository, nil
}

func (s *runControlState) Close() {
	if s == nil {
		return
	}
	s.mu.Lock()
	defer s.mu.Unlock()
	for root, repository := range s.repos {
		_ = repository.Close()
		if logger := s.loggers[root]; logger != nil {
			_ = logger.Close()
			delete(s.loggers, root)
		}
		delete(s.repos, root)
	}
}

func currentRunOwner() (runcontrol.Owner, error) {
	return runcontrol.NewProcessOwner()
}

type controlledRuntime struct {
	base interface {
		StartRun(context.Context, runtimepkg.Request) (runtimepkg.Result, error)
	}
	repository runcontrol.Repository
	owner      runcontrol.Owner
}

func (r controlledRuntime) DeleteSession(ctx context.Context, sessionID string) error {
	deleter, ok := r.base.(interface {
		DeleteSession(context.Context, string) error
	})
	if !ok {
		return nil
	}
	return deleter.DeleteSession(ctx, sessionID)
}

func (r controlledRuntime) DeleteSessions(ctx context.Context, sessionIDs []string) error {
	deleter, ok := r.base.(interface {
		DeleteSessions(context.Context, []string) error
	})
	if !ok {
		for _, sessionID := range sessionIDs {
			if err := r.DeleteSession(ctx, sessionID); err != nil {
				return err
			}
		}
		return nil
	}
	return deleter.DeleteSessions(ctx, sessionIDs)
}

func (r controlledRuntime) DeleteRuntimeStore(ctx context.Context, path string) error {
	deleter, ok := r.base.(interface {
		DeleteRuntimeStore(context.Context, string) error
	})
	if !ok {
		return nil
	}
	return deleter.DeleteRuntimeStore(ctx, path)
}

func controlledRuntimeFor(deps dependencies, workspaceRoot string, effectiveConfig config.Config, base interface {
	StartRun(context.Context, runtimepkg.Request) (runtimepkg.Result, error)
}) (controlledRuntime, error) {
	if deps.runControl == nil {
		return controlledRuntime{}, errors.New("run-control process state is unavailable")
	}
	repository, err := deps.runControl.repository(deps.ctx, workspaceRoot, runControlRetentionPolicy(effectiveConfig))
	if err != nil {
		return controlledRuntime{}, fmt.Errorf("open durable run control: %w", err)
	}
	return controlledRuntime{base: base, repository: repository, owner: deps.runControl.owner}, nil
}

func runControlRetentionPolicy(c config.Config) runcontrol.RetentionPolicy {
	full, _ := time.ParseDuration(c.RunControl.FullHistory)
	tombstone, _ := time.ParseDuration(c.RunControl.TombstoneHistory)
	return runcontrol.RetentionPolicy{FullHistory: full, TombstoneHistory: tombstone, HardQuotaBytes: c.RunControl.WorkspaceQuota}
}

func (r controlledRuntime) StartRun(ctx context.Context, req runtimepkg.Request) (runtimepkg.Result, error) {
	target := targetFromRuntimeRequest(req)
	correlation := runcontrol.Correlation{
		ProductRunID:  boundedSafe(string(runcontrol.ParentRun(ctx))),
		ProductTaskID: boundedSafe(req.TraceID),
	}
	snapshot, err := r.repository.Accept(ctx, runcontrol.Acceptance{
		Target:        target,
		Correlation:   correlation,
		ProductStatus: "accepted",
	})
	if err != nil {
		return runtimepkg.Result{}, fmt.Errorf("durable run acceptance failed: %w", err)
	}
	attempt, _, err := r.repository.Claim(ctx, runcontrol.Claim{
		RunID: snapshot.RunID, Owner: r.owner, Lease: runControlLease, Correlation: correlation,
	})
	if err != nil {
		return runtimepkg.Result{}, fmt.Errorf("durable run ownership failed: %w", err)
	}
	fence := runcontrol.Fence{
		RunID: snapshot.RunID, AttemptID: attempt.ID, OwnerID: r.owner.ID,
		FencingGeneration: attempt.FencingGeneration,
	}

	runCtx, cancel := context.WithCancel(ctx)
	defer cancel()
	req.Metadata = cloneRuntimeMetadata(req.Metadata)
	req.Metadata["run_control_run_id"] = string(snapshot.RunID)
	configuredOnEvent := req.OnEvent
	var eventMu sync.Mutex
	var persistenceErr error
	var progressKey string
	var progressCommittedAt time.Time
	var progressOmitted uint64
	var progressOmittedFirst time.Time
	var progressOmittedLast time.Time
	setPersistenceErr := func(value error) {
		eventMu.Lock()
		defer eventMu.Unlock()
		if persistenceErr == nil {
			persistenceErr = value
			cancel()
		}
	}
	req.OnEvent = func(event runtimepkg.Event) {
		eventMu.Lock()
		defer eventMu.Unlock()
		if persistenceErr != nil {
			return
		}
		draft := runtimeEventDraft(req, event)
		eventAt := event.Time.UTC()
		if eventAt.IsZero() {
			eventAt = time.Now().UTC()
		}
		// Content-aware coalescing: only collapse identical progress payloads within the window.
		// Reasoning/text deltas and tool calls have distinct payload hashes and will not coalesce.
		hash := payloadHash(draft.Payload)
		key := string(draft.Type) + "\x00" + draft.Stage + "\x00" + draft.Task + "\x00" + hash
		elapsed := eventAt.Sub(progressCommittedAt)
		if draft.Type == runcontrol.EventProgress && key == progressKey && elapsed >= 0 && elapsed < runcontrol.ProgressCoalesceWindow {
			if progressOmitted == 0 {
				progressOmittedFirst = eventAt
			}
			progressOmitted++
			progressOmittedLast = eventAt
			return
		}
		if progressOmitted > 0 {
			if draft.Omission == nil {
				draft.Omission = &runcontrol.Omission{Reason: "equivalent progress coalesced"}
			}
			draft.Omission.Count += progressOmitted
			draft.Omission.FirstAt = &progressOmittedFirst
			draft.Omission.LastAt = &progressOmittedLast
			progressOmitted = 0
		}
		if _, _, appendErr := appendRunEventWithRetry(runCtx, r.repository, fence, draft); appendErr != nil {
			persistenceErr = fmt.Errorf("persist runtime event: %w", appendErr)
			cancel()
			return
		}
		if draft.Type == runcontrol.EventProgress {
			progressKey = key
			progressCommittedAt = eventAt
		}
		if configuredOnEvent != nil {
			configuredOnEvent(event)
		}
	}

	controlDone := make(chan struct{})
	go func() {
		defer close(controlDone)
		ticker := time.NewTicker(runcontrol.OwnerTickInterval)
		defer ticker.Stop()
		lastHeartbeat := time.Now()
		lastReconcile := time.Now()
		for {
			select {
			case <-runCtx.Done():
				return
			case now := <-ticker.C:
				snapshot, err := r.repository.Snapshot(runCtx, fence.RunID)
				if err != nil {
					if runCtx.Err() != nil {
						return
					}
					setPersistenceErr(fmt.Errorf("poll durable run control: %w", err))
					return
				}
				if snapshot.Cancellation.State == runcontrol.CancellationRequested {
					if _, _, err := r.repository.AcknowledgeCancellation(runCtx, fence); err != nil {
						setPersistenceErr(fmt.Errorf("acknowledge durable cancellation: %w", err))
						return
					}
					cancel()
					return
				}
				if now.Sub(lastHeartbeat) >= runcontrol.HeartbeatInterval {
					if _, err := r.repository.Heartbeat(runCtx, fence, runControlLease); err != nil {
						if runCtx.Err() != nil {
							return
						}
						setPersistenceErr(fmt.Errorf("persist owner heartbeat: %w", err))
						return
					}
					lastHeartbeat = now
				}
				if now.Sub(lastReconcile) >= runcontrol.ReconciliationInterval {
					if _, err := r.repository.Reconcile(runCtx, runcontrol.NativeProcessProbe{}, runcontrol.ReconcileOptions{}); err != nil {
						if runCtx.Err() != nil {
							return
						}
						setPersistenceErr(fmt.Errorf("reconcile durable runs: %w", err))
						return
					}
					lastReconcile = now
				}
			}
		}
	}()
	result, runErr := r.base.StartRun(runCtx, req)
	eventMu.Lock()
	if persistenceErr == nil && progressOmitted > 0 {
		_, _, appendErr := appendRunEventWithRetry(runCtx, r.repository, fence, runcontrol.EventDraft{
			Type: runcontrol.EventOmission,
			Omission: &runcontrol.Omission{
				Reason: "equivalent progress coalesced", Count: progressOmitted,
				FirstAt: &progressOmittedFirst, LastAt: &progressOmittedLast,
			},
		})
		if appendErr != nil {
			persistenceErr = fmt.Errorf("persist progress omission: %w", appendErr)
		}
	}
	eventMu.Unlock()
	cancel()
	<-controlDone
	eventMu.Lock()
	persistErr := persistenceErr
	eventMu.Unlock()
	if persistErr != nil {
		terminalCtx, terminalCancel := context.WithTimeout(context.Background(), 30*time.Second)
		_, _, terminalErr := proposeRunTerminalWithRetry(terminalCtx, r.repository, fence, runcontrol.TerminalProposal{
			Outcome: runcontrol.TerminalPersistenceLost, Reason: "durable event persistence failed", ProposedBy: r.owner.ID,
		})
		terminalCancel()
		if terminalErr != nil {
			return result, errors.Join(persistErr, terminalErr)
		}
		return result, persistErr
	}

	outcome, reason := terminalOutcome(result, runErr, ctx)
	terminalCtx, terminalCancel := context.WithTimeout(context.Background(), 30*time.Second)
	defer terminalCancel()
	if _, _, err := proposeRunTerminalWithRetry(terminalCtx, r.repository, fence, runcontrol.TerminalProposal{
		Outcome: outcome, Reason: reason, ProposedBy: r.owner.ID,
	}); err != nil {
		return result, errors.Join(runErr, fmt.Errorf("persist terminal run outcome: %w", err))
	}
	return result, runErr
}

func appendRunEventWithRetry(ctx context.Context, repository runcontrol.Repository, fence runcontrol.Fence, draft runcontrol.EventDraft) (runcontrol.Event, runcontrol.Snapshot, error) {
	deadline := time.Now().Add(5 * time.Second)
	for {
		event, snapshot, err := repository.Append(ctx, fence, draft)
		if err == nil || !retryableRunControlError(err) || !time.Now().Before(deadline) {
			return event, snapshot, err
		}
		if err := waitRunControlRetry(ctx, deadline); err != nil {
			return runcontrol.Event{}, runcontrol.Snapshot{}, err
		}
	}
}

func proposeRunTerminalWithRetry(ctx context.Context, repository runcontrol.Repository, fence runcontrol.Fence, proposal runcontrol.TerminalProposal) (runcontrol.Snapshot, bool, error) {
	for {
		snapshot, won, err := repository.ProposeTerminal(ctx, fence, proposal)
		if err == nil || !retryableRunControlError(err) {
			return snapshot, won, err
		}
		if err := waitRunControlRetry(ctx, time.Now().Add(250*time.Millisecond)); err != nil {
			return runcontrol.Snapshot{}, false, err
		}
	}
}

func retryableRunControlError(err error) bool {
	return errors.Is(err, runcontrol.ErrUnavailable) || errors.Is(err, runcontrol.ErrBusy)
}

func waitRunControlRetry(ctx context.Context, deadline time.Time) error {
	wait := time.Until(deadline)
	if wait > 100*time.Millisecond {
		wait = 100 * time.Millisecond
	}
	if wait <= 0 {
		return context.DeadlineExceeded
	}
	timer := time.NewTimer(wait)
	defer timer.Stop()
	select {
	case <-ctx.Done():
		return ctx.Err()
	case <-timer.C:
		return nil
	}
}

func targetFromRuntimeRequest(req runtimepkg.Request) runcontrol.Target {
	target := runcontrol.Target{
		Kind:      boundedSafe(req.PromptRef.OwnerKind),
		Operation: boundedSafe(req.PromptRef.Purpose),
		Project:   boundedSafe(req.Metadata["project"]),
		Sprint:    boundedSafe(req.Metadata["sprint"]),
		Study:     boundedSafe(req.Metadata["study"]),
		Stage:     boundedSafe(req.Metadata["stage"]),
		Task:      boundedSafe(firstSafeValue(req.Metadata["task"], req.Metadata["task.kind"], req.Metadata["coverage"])),
	}
	if target.Kind == "" {
		if target.Study != "" {
			target.Kind = "study"
		} else if target.Sprint != "" {
			target.Kind = "sprint"
		} else {
			target.Kind = "runtime"
		}
	}
	if target.Operation == "" {
		target.Operation = boundedSafe(firstSafeValue(target.Stage, req.Metadata["task.kind"], req.PromptRef.ID, "runtime"))
	}
	return target
}

func runtimeEventDraft(req runtimepkg.Request, event runtimepkg.Event) runcontrol.EventDraft {
	eventType := runcontrol.EventProgress
	lowerType := strings.ToLower(strings.TrimSpace(event.Type))
	lowerKind := strings.ToLower(strings.TrimSpace(event.Kind))
	switch lowerType {
	case "warning", "warn", "error":
		eventType = runcontrol.EventWarning
	case "artifact", "file":
		eventType = runcontrol.EventArtifact
	case "finding":
		eventType = runcontrol.EventFinding
	case "message", "text", "output", "assistant_text", "reasoning_text", "reasoning", "content", "delta":
		eventType = runcontrol.EventMessage
	default:
		// Kind-based fallback: reasoning and message kinds should be visible as message, not coalesced progress.
		switch lowerKind {
		case "message", "reasoning", "assistant", "assistant_text", "reasoning_text":
			eventType = runcontrol.EventMessage
		case "tool", "tool_use", "tool_call", "tool_call_update":
			// Tools stay as progress but with distinct payload so coalescing can distinguish.
			eventType = runcontrol.EventProgress
		}
	}
	payload := map[string]string{
		"runtime_event_id": boundedSafe(event.ID),
		"runtime_run_id":   boundedSafe(event.RunID),
		"session_id":       boundedSafe(event.SessionID),
		"type":             boundedSafe(event.Type),
		"kind":             boundedSafe(event.Kind),
	}
	if lowerKind == "tool" || lowerKind == "tool_use" || lowerKind == "tool_call" || lowerKind == "tool_call_update" {
		captureToolObservation(payload, event.Payload)
	}
	// Preserve safe observable payload fields into durable storage for observability.
	// Deny sensitive keys and truncate values to runcontrol-safe limits.
	// Flatten one level of nesting so tool/action names buried in maps are surfaced as top-level payload keys
	// that the run timeline JS expects (payload.tool, payload.action, payload.title, etc.).
	for key, value := range event.Payload {
		if isSensitivePayloadKey(key) {
			continue
		}
		normalized := strings.TrimSpace(key)
		if normalized == "" || len(normalized) > 128 || strings.ContainsAny(normalized, "\x00\r\n") {
			continue
		}
		if normalized == "type" || normalized == "kind" {
			continue
		}
		if nested, ok := value.(map[string]any); ok {
			for subKey, subVal := range nested {
				if isSensitivePayloadKey(subKey) {
					continue
				}
				subNorm := strings.TrimSpace(subKey)
				if subNorm == "" || len(subNorm) > 128 || strings.ContainsAny(subNorm, "\x00\r\n") {
					continue
				}
				if _, exists := payload[subNorm]; exists {
					continue
				}
				// Promote common observable sub-keys; namespace the rest to avoid collisions.
				promote := map[string]bool{"tool": true, "title": true, "detail": true, "text": true, "delta": true, "content": true, "message": true, "action": true, "state": true, "status": true, "native_type": true, "line": true}
				targetKey := subNorm
				if !promote[subNorm] {
					targetKey = normalized + "_" + subNorm
					if len(targetKey) > 128 {
						continue
					}
				}
				if _, exists := payload[targetKey]; exists {
					continue
				}
				str := payloadValueString(subVal)
				if strings.TrimSpace(str) == "" {
					continue
				}
				if len(payload) >= 30 {
					break
				}
				payload[targetKey] = boundedPayloadValue(str)
			}
			// Also keep a compact stringified top-level for debugging if not promoted.
			if len(payload) < 30 {
				if _, exists := payload[normalized]; !exists {
					str := payloadValueString(value)
					if strings.TrimSpace(str) != "" && !strings.HasPrefix(str, "[map omitted") {
						payload[normalized] = boundedPayloadValue(str)
					}
				}
			}
			continue
		}
		str := payloadValueString(value)
		if strings.TrimSpace(str) == "" {
			continue
		}
		if len(payload) >= 30 {
			break
		}
		if _, exists := payload[normalized]; exists {
			continue
		}
		payload[normalized] = boundedPayloadValue(str)
	}
	// Ensure the most useful display keys are always present even if nested.
	for _, want := range []string{"tool", "action", "title", "detail", "text", "delta"} {
		if _, ok := payload[want]; ok {
			continue
		}
		if v := findNestedString(event.Payload, want); v != "" {
			payload[want] = boundedPayloadValue(v)
		}
	}
	omission := (*runcontrol.Omission)(nil)
	if event.RawPresent || event.RawOmitted {
		reason := firstSafeValue(event.RawOmissionReason, "runtime payload omitted by safe persistence policy")
		omission = &runcontrol.Omission{Reason: boundedSafe(reason), Count: 1}
	} else if len(event.Payload) > len(payload)-5 {
		// Payload had more fields than we persisted (truncated/omitted keys) – record for diagnostics but don't hide persisted fields.
		omission = &runcontrol.Omission{Reason: boundedSafe("runtime payload truncated to safe observable fields"), Count: 1}
	}
	return runcontrol.EventDraft{
		Type: eventType, Scope: runcontrol.EventScopeRuntime,
		Stage: boundedSafe(req.Metadata["stage"]), Task: boundedSafe(firstSafeValue(req.Metadata["task"], req.Metadata["task.kind"])),
		Kind: payload["kind"], Tool: payload["tool"], Action: payload["action"],
		Reason: payload["reason"], Detail: firstSafeValue(payload["detail"], payload["title"]),
		Payload: payload, Omission: omission,
	}
}

func isSensitivePayloadKey(key string) bool {
	lower := strings.ToLower(key)
	for _, marker := range []string{"secret", "token", "password", "authorization", "cookie", "api_key", "apikey", "credential", "auth"} {
		if strings.Contains(lower, marker) {
			return true
		}
	}
	return false
}

func findNestedString(payload map[string]any, want string) string {
	for _, v := range payload {
		if m, ok := v.(map[string]any); ok {
			if s, ok := m[want].(string); ok && strings.TrimSpace(s) != "" {
				return s
			}
			// One more level deep (common for opencode part.state structures)
			for _, inner := range m {
				if innerMap, ok := inner.(map[string]any); ok {
					if s, ok := innerMap[want].(string); ok && strings.TrimSpace(s) != "" {
						return s
					}
				}
			}
		}
	}
	return ""
}

func payloadValueString(value any) string {
	switch v := value.(type) {
	case string:
		return v
	case []byte:
		if len(v) == 0 {
			return ""
		}
		return string(v)
	case bool:
		if v {
			return "true"
		}
		return "false"
	case int:
		return fmt.Sprintf("%d", v)
	case int8:
		return fmt.Sprintf("%d", v)
	case int16:
		return fmt.Sprintf("%d", v)
	case int32:
		return fmt.Sprintf("%d", v)
	case int64:
		return fmt.Sprintf("%d", v)
	case uint, uint8, uint16, uint32, uint64:
		return fmt.Sprintf("%d", v)
	case float32, float64:
		return fmt.Sprintf("%v", v)
	case map[string]any, map[string]string, []any, []string:
		// Encode structured values compactly.
		encoded, err := jsonMarshalTruncated(v)
		if err != nil {
			return fmt.Sprintf("%v", v)
		}
		return encoded
	default:
		return fmt.Sprintf("%v", v)
	}
}

func jsonMarshalTruncated(v any) (string, error) {
	encoded, err := json.Marshal(v)
	if err != nil {
		return "", err
	}
	return string(encoded), nil
}

func captureToolObservation(out map[string]string, payload map[string]any) {
	for target, aliases := range map[string][]string{
		"tool_call_id": {"tool_call_id", "toolCallId", "call_id", "callID"},
		"tool_name":    {"tool_name", "toolName", "tool", "name"},
		"tool_status":  {"tool_status", "status", "phase"},
	} {
		if value := findNestedPayloadValue(payload, aliases, 0); value != nil {
			if text, ok := value.(string); ok && strings.TrimSpace(text) != "" {
				out[target] = boundedPayloadValue(text)
			}
		}
	}
	for target, aliases := range map[string][]string{
		"tool_arguments": {"tool_arguments", "arguments", "args", "input", "parameters"},
		"tool_result":    {"tool_result", "result", "output", "content"},
		"tool_error":     {"tool_error", "error"},
	} {
		value := findNestedPayloadValue(payload, aliases, 0)
		if value == nil {
			continue
		}
		encoded, err := json.Marshal(redactObservableValue(value))
		if err == nil && string(encoded) != "null" {
			out[target] = boundedPayloadValue(string(encoded))
		}
	}
	if out["tool"] == "" {
		out["tool"] = out["tool_name"]
	}
}

func findNestedPayloadValue(value any, aliases []string, depth int) any {
	if depth > 5 {
		return nil
	}
	switch typed := value.(type) {
	case map[string]any:
		for _, key := range aliases {
			if found, ok := typed[key]; ok && found != nil {
				return found
			}
		}
		keys := make([]string, 0, len(typed))
		for key := range typed {
			keys = append(keys, key)
		}
		sort.Strings(keys)
		for _, key := range keys {
			if found := findNestedPayloadValue(typed[key], aliases, depth+1); found != nil {
				return found
			}
		}
	case []any:
		for _, item := range typed {
			if found := findNestedPayloadValue(item, aliases, depth+1); found != nil {
				return found
			}
		}
	}
	return nil
}

func redactObservableValue(value any) any {
	switch typed := value.(type) {
	case map[string]any:
		redacted := make(map[string]any, len(typed))
		for key, item := range typed {
			if isSensitivePayloadKey(key) {
				redacted[key] = "[REDACTED]"
			} else {
				redacted[key] = redactObservableValue(item)
			}
		}
		return redacted
	case []any:
		redacted := make([]any, len(typed))
		for index, item := range typed {
			redacted[index] = redactObservableValue(item)
		}
		return redacted
	case string:
		lower := strings.ToLower(typed)
		for _, marker := range []string{"bearer ", "sk-", "ghp_", "github_pat_", "-----begin private key"} {
			if strings.Contains(lower, marker) {
				return "[REDACTED]"
			}
		}
		return typed
	default:
		return value
	}
}

func boundedPayloadValue(value string) string {
	value = strings.Map(func(r rune) rune {
		if r == 0 || r == '\r' || r == '\n' {
			return -1
		}
		return r
	}, strings.TrimSpace(value))
	if len(value) > runcontrol.MaxSafeValueBytes {
		value = value[:runcontrol.MaxSafeValueBytes]
	}
	return value
}

func payloadHash(payload map[string]string) string {
	if len(payload) == 0 {
		return ""
	}
	// Stable hash of payload content for coalescing: include type/kind and any payload_* keys.
	keys := make([]string, 0, len(payload))
	for k := range payload {
		if k == "runtime_event_id" || k == "runtime_run_id" || k == "session_id" {
			continue
		}
		keys = append(keys, k)
	}
	// Keep deterministic order by sorting.
	sortStrings(keys)
	var b strings.Builder
	for _, k := range keys {
		b.WriteString(k)
		b.WriteString("=")
		b.WriteString(payload[k])
		b.WriteString("\x00")
	}
	return b.String()
}

func sortStrings(values []string) {
	// Insertion sort for small slices – avoid importing sort for minimal diff; keep stdlib sort if available.
	for i := 1; i < len(values); i++ {
		j := i
		for j > 0 && values[j-1] > values[j] {
			values[j-1], values[j] = values[j], values[j-1]
			j--
		}
	}
}

func terminalOutcome(result runtimepkg.Result, runErr error, parent context.Context) (runcontrol.TerminalOutcome, string) {
	status := strings.ToLower(strings.TrimSpace(result.Status))
	switch {
	case errors.Is(runErr, context.DeadlineExceeded), errors.Is(parent.Err(), context.DeadlineExceeded), result.Error != nil && result.Error.Category == "timeout":
		return runcontrol.TerminalTimedOut, "runtime deadline exceeded"
	case errors.Is(runErr, context.Canceled), errors.Is(parent.Err(), context.Canceled), status == "cancelled", result.Error != nil && result.Error.Category == "cancellation":
		return runcontrol.TerminalCancelled, "runtime cancelled"
	case runErr != nil, status == "failed", status == "error":
		return runcontrol.TerminalFailed, "runtime failed"
	default:
		return runcontrol.TerminalSucceeded, "runtime completed"
	}
}

func cloneRuntimeMetadata(input map[string]string) map[string]string {
	out := make(map[string]string, len(input)+1)
	for key, value := range input {
		out[key] = value
	}
	return out
}

func boundedSafe(value string) string {
	value = strings.Map(func(r rune) rune {
		if r == 0 || r == '\r' || r == '\n' {
			return -1
		}
		return r
	}, strings.TrimSpace(value))
	if len(value) > runcontrol.MaxTargetFieldBytes {
		value = value[:runcontrol.MaxTargetFieldBytes]
	}
	return value
}

func firstSafeValue(values ...string) string {
	for _, value := range values {
		if strings.TrimSpace(value) != "" {
			return value
		}
	}
	return ""
}

package runcontrol

import (
	"context"
	"database/sql"
	"encoding/base64"
	"encoding/json"
	"errors"
	"fmt"
	"strings"
	"time"
)

func (r *SQLiteRepository) Heartbeat(ctx context.Context, fence Fence, lease time.Duration) (Snapshot, error) {
	if ctx == nil {
		ctx = context.Background()
	}
	if err := fence.Validate(); err != nil {
		return Snapshot{}, err
	}
	if lease <= 0 {
		return Snapshot{}, invalidField("lease", "must be positive")
	}
	if usage, err := r.storageBytes(); err != nil {
		return Snapshot{}, err
	} else if usage >= r.retention.HardQuotaBytes {
		return Snapshot{}, runError(CodeQuota, "heartbeat_quota", fence.RunID, "hard quota requires the owner to stop active work", true, nil)
	}
	now := r.now()
	tx, err := r.db.BeginTx(ctx, nil)
	if err != nil {
		return Snapshot{}, classifyStoreError("heartbeat_begin", "begin owner heartbeat failed", err)
	}
	defer tx.Rollback()
	if err := verifyFence(ctx, tx, fence); err != nil {
		return Snapshot{}, err
	}
	result, err := tx.ExecContext(ctx, `
UPDATE attempts SET heartbeat_at = ?, lease_expires_at = ?
WHERE run_id = ? AND attempt_id = ? AND owner_id = ? AND fencing_generation = ? AND outcome IS NULL`,
		formatTime(now), formatTime(now.Add(lease)), string(fence.RunID), string(fence.AttemptID), fence.OwnerID, fence.FencingGeneration)
	if err != nil {
		return Snapshot{}, classifyStoreError("heartbeat", "persist owner heartbeat failed", err)
	}
	if changed, err := result.RowsAffected(); err != nil || changed != 1 {
		return Snapshot{}, runError(CodeStaleFence, "heartbeat", fence.RunID, "owner heartbeat lost its authoritative fence", false, err)
	}
	result, err = tx.ExecContext(ctx, `UPDATE runs SET liveness = ?, updated_at = ? WHERE run_id = ? AND current_attempt_id = ? AND terminal_outcome IS NULL`,
		string(LivenessLive), formatTime(now), string(fence.RunID), string(fence.AttemptID))
	if err != nil {
		return Snapshot{}, classifyStoreError("heartbeat_snapshot", "update heartbeat snapshot failed", err)
	}
	if changed, err := result.RowsAffected(); err != nil || changed != 1 {
		return Snapshot{}, runError(CodeStaleFence, "heartbeat", fence.RunID, "run is no longer owned by heartbeat attempt", false, err)
	}
	snapshot, err := loadSnapshot(ctx, tx, fence.RunID)
	if err != nil {
		return Snapshot{}, err
	}
	if err := tx.Commit(); err != nil {
		return Snapshot{}, classifyStoreError("heartbeat_commit", "commit owner heartbeat failed", err)
	}
	r.log(ctx, LogDebug, "run owner heartbeat committed",
		LogField{Key: "run_id", Value: string(fence.RunID)}, LogField{Key: "attempt_id", Value: string(fence.AttemptID)},
		LogField{Key: "owner_id", Value: fence.OwnerID}, LogField{Key: "fencing_generation", Value: fmt.Sprint(fence.FencingGeneration)})
	r.metrics.leaseRenewals.Add(1)
	return snapshot, nil
}

func (r *SQLiteRepository) RequestCancellation(ctx context.Context, runID RunID, reason string) (Snapshot, bool, error) {
	if ctx == nil {
		ctx = context.Background()
	}
	if err := runID.Validate(); err != nil {
		return Snapshot{}, false, err
	}
	reason = strings.TrimSpace(reason)
	if reason == "" || len(reason) > MaxSafeValueBytes || strings.ContainsAny(reason, "\x00\r\n") {
		return Snapshot{}, false, invalidField("cancellation.reason", "must be a bounded canonical reason")
	}
	now := r.now()
	tx, err := r.db.BeginTx(ctx, nil)
	if err != nil {
		return Snapshot{}, false, classifyStoreError("cancel_begin", "begin cancellation request failed", err)
	}
	defer tx.Rollback()
	current, err := loadSnapshot(ctx, tx, runID)
	if err != nil {
		return Snapshot{}, false, err
	}
	if current.Terminal != nil || current.Cancellation.State != CancellationNone {
		if err := tx.Commit(); err != nil {
			return Snapshot{}, false, classifyStoreError("cancel_read_commit", "finish cancellation state read failed", err)
		}
		return current, false, nil
	}
	sequence := current.LastSequence + 1
	payload, err := marshalBounded(map[string]string{"state": string(CancellationRequested), "reason": reason}, MaxSafeValueBytes*2)
	if err != nil {
		return Snapshot{}, false, err
	}
	var attemptValue any
	if current.CurrentAttemptID != "" {
		attemptValue = string(current.CurrentAttemptID)
	}
	if _, err := tx.ExecContext(ctx, `INSERT INTO events (run_id, sequence, committed_at, event_type, attempt_id, payload_json)
VALUES (?, ?, ?, 'cancellation', ?, ?)`, string(runID), sequence, formatTime(now), attemptValue, payload); err != nil {
		return Snapshot{}, false, classifyStoreError("cancel_event", "persist cancellation event failed", err)
	}
	result, err := tx.ExecContext(ctx, `
UPDATE runs SET lifecycle = ?, cancellation_state = ?, cancellation_reason = ?, cancellation_requested_at = ?, updated_at = ?, last_sequence = ?
WHERE run_id = ? AND terminal_outcome IS NULL AND cancellation_state = ? AND last_sequence = ?`,
		string(LifecycleCancelling), string(CancellationRequested), reason, formatTime(now), formatTime(now), sequence,
		string(runID), string(CancellationNone), current.LastSequence)
	if err != nil {
		return Snapshot{}, false, classifyStoreError("cancel", "persist cancellation request failed", err)
	}
	if changed, err := result.RowsAffected(); err != nil || changed != 1 {
		return Snapshot{}, false, runError(CodeConflict, "cancel", runID, "cancellation state changed concurrently", true, err)
	}
	snapshot, err := loadSnapshot(ctx, tx, runID)
	if err != nil {
		return Snapshot{}, false, err
	}
	if err := tx.Commit(); err != nil {
		return Snapshot{}, false, classifyStoreError("cancel_commit", "commit cancellation request failed", err)
	}
	r.notify(runID, sequence)
	r.log(ctx, LogInfo, "run cancellation requested",
		LogField{Key: "run_id", Value: string(runID)}, LogField{Key: "sequence", Value: fmt.Sprint(sequence)},
		LogField{Key: "cancellation_state", Value: string(snapshot.Cancellation.State)}, LogField{Key: "cancellation_reason", Value: reason})
	r.metrics.cancellationRequests.Add(1)
	return snapshot, true, nil
}

func (r *SQLiteRepository) AcknowledgeCancellation(ctx context.Context, fence Fence) (Snapshot, bool, error) {
	if ctx == nil {
		ctx = context.Background()
	}
	if err := fence.Validate(); err != nil {
		return Snapshot{}, false, err
	}
	now := r.now()
	tx, err := r.db.BeginTx(ctx, nil)
	if err != nil {
		return Snapshot{}, false, classifyStoreError("cancel_ack_begin", "begin cancellation acknowledgement failed", err)
	}
	defer tx.Rollback()
	if err := verifyFence(ctx, tx, fence); err != nil {
		return Snapshot{}, false, err
	}
	current, err := loadSnapshot(ctx, tx, fence.RunID)
	if err != nil {
		return Snapshot{}, false, err
	}
	if current.Terminal != nil || current.Cancellation.State == CancellationAcknowledged {
		if err := tx.Commit(); err != nil {
			return Snapshot{}, false, classifyStoreError("cancel_ack_read_commit", "finish cancellation acknowledgement read failed", err)
		}
		return current, false, nil
	}
	if current.Cancellation.State != CancellationRequested {
		return Snapshot{}, false, runError(CodeConflict, "cancel_ack", fence.RunID, "cancellation has not been requested", false, nil)
	}
	sequence := current.LastSequence + 1
	payload, _ := marshalBounded(map[string]string{"state": string(CancellationAcknowledged)}, MaxSafeValueBytes)
	if _, err := tx.ExecContext(ctx, `INSERT INTO events (run_id, sequence, committed_at, event_type, attempt_id, payload_json)
VALUES (?, ?, ?, 'cancellation', ?, ?)`, string(fence.RunID), sequence, formatTime(now), string(fence.AttemptID), payload); err != nil {
		return Snapshot{}, false, classifyStoreError("cancel_ack_event", "persist cancellation acknowledgement event failed", err)
	}
	result, err := tx.ExecContext(ctx, `
UPDATE runs SET cancellation_state = ?, cancellation_acknowledged_at = ?, updated_at = ?, last_sequence = ?
WHERE run_id = ? AND current_attempt_id = ? AND cancellation_state = ? AND terminal_outcome IS NULL AND last_sequence = ?`,
		string(CancellationAcknowledged), formatTime(now), formatTime(now), sequence, string(fence.RunID), string(fence.AttemptID),
		string(CancellationRequested), current.LastSequence)
	if err != nil {
		return Snapshot{}, false, classifyStoreError("cancel_ack", "persist cancellation acknowledgement failed", err)
	}
	if changed, err := result.RowsAffected(); err != nil || changed != 1 {
		return Snapshot{}, false, runError(CodeStaleFence, "cancel_ack", fence.RunID, "cancellation acknowledgement lost its fence", false, err)
	}
	snapshot, err := loadSnapshot(ctx, tx, fence.RunID)
	if err != nil {
		return Snapshot{}, false, err
	}
	if err := tx.Commit(); err != nil {
		return Snapshot{}, false, classifyStoreError("cancel_ack_commit", "commit cancellation acknowledgement failed", err)
	}
	r.notify(fence.RunID, sequence)
	r.log(ctx, LogInfo, "run cancellation acknowledged",
		LogField{Key: "run_id", Value: string(fence.RunID)}, LogField{Key: "attempt_id", Value: string(fence.AttemptID)},
		LogField{Key: "sequence", Value: fmt.Sprint(sequence)}, LogField{Key: "cancellation_state", Value: string(snapshot.Cancellation.State)})
	return snapshot, true, nil
}

func (r *SQLiteRepository) List(ctx context.Context, query Query) (Page, error) {
	limit := query.Limit
	if limit == 0 {
		limit = 50
	}
	if limit < 1 || limit > 200 {
		return Page{}, invalidField("query.limit", "must be between 1 and 200")
	}
	clauses := []string{"1=1"}
	args := make([]any, 0, 8)
	if len(query.Lifecycle) > 0 {
		parts := make([]string, 0, len(query.Lifecycle))
		for _, lifecycle := range query.Lifecycle {
			if !lifecycle.IsValid() {
				return Page{}, invalidField("query.lifecycle", "contains an unknown state")
			}
			parts = append(parts, "?")
			args = append(args, string(lifecycle))
		}
		clauses = append(clauses, "lifecycle IN ("+strings.Join(parts, ",")+")")
	}
	for column, value := range map[string]string{
		"target_kind": query.TargetKind, "project_id": query.Project, "sprint_id": query.Sprint, "study_id": query.Study,
	} {
		if value != "" {
			clauses = append(clauses, column+" = ?")
			args = append(args, value)
		}
	}
	if query.After != "" {
		cursor, err := decodeRunCursor(query.After)
		if err != nil {
			return Page{}, err
		}
		clauses = append(clauses, "(updated_at < ? OR (updated_at = ? AND run_id < ?))")
		args = append(args, cursor.UpdatedAt, cursor.UpdatedAt, string(cursor.RunID))
	}
	rows, err := r.db.QueryContext(ctx, `SELECT run_id, updated_at FROM runs WHERE `+strings.Join(clauses, " AND ")+` ORDER BY updated_at DESC, run_id DESC LIMIT ?`, append(args, limit+1)...)
	if err != nil {
		return Page{}, classifyStoreError("list", "list runs failed", err)
	}
	defer rows.Close()
	type listedRun struct {
		id        RunID
		updatedAt string
	}
	listed := make([]listedRun, 0, limit+1)
	for rows.Next() {
		var item listedRun
		if err := rows.Scan(&item.id, &item.updatedAt); err != nil {
			return Page{}, classifyStoreError("list_scan", "decode run list failed", err)
		}
		listed = append(listed, item)
	}
	if err := rows.Err(); err != nil {
		return Page{}, classifyStoreError("list_rows", "read run list failed", err)
	}
	page := Page{Runs: make([]Snapshot, 0, min(limit, len(listed)))}
	if len(listed) > limit {
		page.NextCursor = encodeRunCursor(runCursor{UpdatedAt: listed[limit-1].updatedAt, RunID: listed[limit-1].id})
		listed = listed[:limit]
	}
	for _, item := range listed {
		snapshot, err := r.Snapshot(ctx, item.id)
		if err != nil {
			return Page{}, err
		}
		page.Runs = append(page.Runs, snapshot)
	}
	return page, nil
}

type runCursor struct {
	UpdatedAt string `json:"updated_at"`
	RunID     RunID  `json:"run_id"`
}

func encodeRunCursor(cursor runCursor) string {
	encoded, _ := json.Marshal(cursor)
	return base64.RawURLEncoding.EncodeToString(encoded)
}

func decodeRunCursor(value string) (runCursor, error) {
	encoded, err := base64.RawURLEncoding.DecodeString(value)
	if err != nil || len(encoded) > 1024 {
		return runCursor{}, invalidField("query.after", "is not a valid opaque cursor")
	}
	var cursor runCursor
	if err := json.Unmarshal(encoded, &cursor); err != nil || cursor.UpdatedAt == "" || cursor.RunID.Validate() != nil {
		return runCursor{}, invalidField("query.after", "is not a valid opaque cursor")
	}
	if _, err := parseTime(cursor.UpdatedAt); err != nil {
		return runCursor{}, invalidField("query.after", "is not a valid opaque cursor")
	}
	return cursor, nil
}

type reconciliationCandidate struct {
	runID      RunID
	attemptID  AttemptID
	ownerID    string
	generation uint64
	process    ProcessIdentity
}

func (r *SQLiteRepository) Reconcile(ctx context.Context, probe ProcessProbe, opts ReconcileOptions) (ReconcileReport, error) {
	if probe == nil {
		return ReconcileReport{}, invalidField("process_probe", "is required")
	}
	grace := opts.Grace
	if grace == 0 {
		grace = ReconciliationGrace
	}
	if grace < 0 {
		return ReconcileReport{}, invalidField("reconciliation.grace", "must not be negative")
	}
	limit := opts.Limit
	if limit == 0 {
		limit = DefaultReconcileBatch
	}
	if limit < 1 || limit > MaximumReconcileBatch {
		return ReconcileReport{}, invalidField("reconciliation.limit", fmt.Sprintf("must be between 1 and %d", MaximumReconcileBatch))
	}
	report := ReconcileReport{Decisions: make([]ReconcileDecision, 0, limit)}
	acceptedPredicate, acceptedArgs := r.expiredTimestampPredicate("accepted_at", grace)
	unclaimedRows, err := r.db.QueryContext(ctx, `
SELECT run_id FROM runs
WHERE terminal_outcome IS NULL AND current_attempt_id IS NULL AND `+acceptedPredicate+`
ORDER BY accepted_at ASC, run_id ASC LIMIT ?`, append(acceptedArgs, limit)...)
	if err != nil {
		return ReconcileReport{}, classifyStoreError("reconcile_scan", "scan unclaimed runs failed", err)
	}
	var unclaimed []RunID
	for unclaimedRows.Next() {
		var runID RunID
		if err := unclaimedRows.Scan(&runID); err != nil {
			unclaimedRows.Close()
			return ReconcileReport{}, classifyStoreError("reconcile_scan", "decode unclaimed run failed", err)
		}
		unclaimed = append(unclaimed, runID)
	}
	if err := unclaimedRows.Close(); err != nil {
		return ReconcileReport{}, classifyStoreError("reconcile_scan", "close unclaimed run scan failed", err)
	}
	for _, runID := range unclaimed {
		won, err := r.reconcileUnclaimed(ctx, runID)
		if err != nil {
			return report, err
		}
		if !won {
			continue
		}
		report.Scanned++
		report.Terminal++
		decision := "owner_never_claimed_after_grace"
		candidate := reconciliationCandidate{runID: runID}
		_ = r.recordReconciliation(ctx, candidate, "terminal_proposal", decision)
		report.Decisions = append(report.Decisions, ReconcileDecision{RunID: runID, Action: "terminal_proposal", Decision: decision})
	}
	remaining := limit - report.Scanned
	if remaining == 0 {
		r.finishReconciliationLog(ctx, &report)
		return report, nil
	}
	predicate, predicateArgs := r.expiredLeasePredicate(grace)
	queryArgs := append(predicateArgs, remaining)
	rows, err := r.db.QueryContext(ctx, `
SELECT runs.run_id, attempts.attempt_id, attempts.owner_id, attempts.fencing_generation,
       attempts.host_digest, attempts.boot_id, attempts.pid, attempts.process_birth_token
FROM runs JOIN attempts ON attempts.attempt_id = runs.current_attempt_id
WHERE runs.terminal_outcome IS NULL AND `+predicate+`
ORDER BY attempts.lease_expires_at ASC, runs.run_id ASC LIMIT ?`, queryArgs...)
	if err != nil {
		return ReconcileReport{}, classifyStoreError("reconcile_scan", "scan expired run owners failed", err)
	}
	var candidates []reconciliationCandidate
	for rows.Next() {
		var candidate reconciliationCandidate
		if err := rows.Scan(&candidate.runID, &candidate.attemptID, &candidate.ownerID, &candidate.generation,
			&candidate.process.HostDigest, &candidate.process.BootID, &candidate.process.PID, &candidate.process.BirthToken); err != nil {
			rows.Close()
			return ReconcileReport{}, classifyStoreError("reconcile_scan", "decode expired run owner failed", err)
		}
		candidates = append(candidates, candidate)
	}
	if err := rows.Close(); err != nil {
		return ReconcileReport{}, classifyStoreError("reconcile_scan", "close expired owner scan failed", err)
	}
	report.Scanned += len(candidates)
	for _, candidate := range candidates {
		observed, probeErr := probe.Probe(ctx, candidate.process.PID)
		decision, outcome := reconcileProcessDecision(candidate.process, observed, probeErr)
		action := "terminal_proposal"
		if outcome == "" {
			action = "mark_stalled"
			if err := r.markStalled(ctx, candidate); err != nil {
				if errors.Is(err, ErrTerminal) || errors.Is(err, ErrStaleFence) {
					continue
				}
				return report, err
			}
			report.Stalled++
		} else {
			fence := Fence{RunID: candidate.runID, AttemptID: candidate.attemptID, OwnerID: candidate.ownerID, FencingGeneration: candidate.generation}
			_, won, err := r.ProposeTerminal(ctx, fence, TerminalProposal{Outcome: outcome, Reason: decision, ProposedBy: "reconciler"})
			if err != nil && !errors.Is(err, ErrTerminal) && !errors.Is(err, ErrStaleFence) {
				return report, err
			}
			if won {
				report.Terminal++
				if outcome == TerminalCleanupUncertain {
					report.Uncertain++
				}
			}
		}
		_ = r.recordReconciliation(ctx, candidate, action, decision)
		report.Decisions = append(report.Decisions, ReconcileDecision{RunID: candidate.runID, AttemptID: candidate.attemptID, Action: action, Decision: decision})
	}
	r.finishReconciliationLog(ctx, &report)
	return report, nil
}

func (r *SQLiteRepository) finishReconciliationLog(ctx context.Context, report *ReconcileReport) {
	r.log(ctx, LogInfo, "run reconciliation completed",
		LogField{Key: "reconciliation_scanned", Value: fmt.Sprint(report.Scanned)},
		LogField{Key: "reconciliation_stalled", Value: fmt.Sprint(report.Stalled)},
		LogField{Key: "reconciliation_terminal", Value: fmt.Sprint(report.Terminal)},
		LogField{Key: "reconciliation_uncertain", Value: fmt.Sprint(report.Uncertain)})
	r.metrics.reconciliations.Add(1)
}

func (r *SQLiteRepository) reconcileUnclaimed(ctx context.Context, runID RunID) (wonResult bool, resultErr error) {
	metricStarted := time.Now()
	defer func() { r.metrics.terminal.observe(metricStarted, resultErr) }()
	now := r.now()
	tx, err := r.db.BeginTx(ctx, nil)
	if err != nil {
		return false, classifyStoreError("reconcile_unclaimed_begin", "begin unclaimed reconciliation failed", err)
	}
	defer tx.Rollback()
	current, err := loadSnapshot(ctx, tx, runID)
	if err != nil {
		if errors.Is(err, ErrNotFound) {
			return false, nil
		}
		return false, err
	}
	if current.Terminal != nil || current.CurrentAttemptID != "" {
		return false, nil
	}
	sequence := current.LastSequence + 1
	reason := "owner_never_claimed_after_grace"
	payload, err := marshalBounded(map[string]string{"outcome": string(TerminalInterrupted), "reason": reason}, MaxSafeValueBytes*2)
	if err != nil {
		return false, err
	}
	if _, err := tx.ExecContext(ctx, `INSERT INTO events (run_id, sequence, committed_at, event_type, payload_json)
VALUES (?, ?, ?, 'terminal', ?)`, string(runID), sequence, formatTime(now), payload); err != nil {
		return false, classifyStoreError("reconcile_unclaimed_event", "persist unclaimed terminal event failed", err)
	}
	result, err := tx.ExecContext(ctx, `UPDATE runs SET lifecycle = ?, liveness = ?, finished_at = ?, updated_at = ?, last_sequence = ?,
terminal_outcome = ?, terminal_reason = ?, terminal_at = ?, terminal_proposed_by = 'reconciler'
WHERE run_id = ? AND current_attempt_id IS NULL AND terminal_outcome IS NULL`,
		string(LifecycleInterrupted), string(LivenessTerminal), formatTime(now), formatTime(now), sequence,
		string(TerminalInterrupted), reason, formatTime(now), string(runID))
	if err != nil {
		return false, classifyStoreError("reconcile_unclaimed_cas", "persist unclaimed terminal state failed", err)
	}
	changed, err := result.RowsAffected()
	if err != nil {
		return false, classifyStoreError("reconcile_unclaimed_cas", "inspect unclaimed terminal state failed", err)
	}
	if changed != 1 {
		return false, nil
	}
	if err := tx.Commit(); err != nil {
		return false, classifyStoreError("reconcile_unclaimed_commit", "commit unclaimed reconciliation failed", err)
	}
	r.notify(runID, sequence)
	r.log(ctx, LogInfo, "unclaimed run reconciled",
		LogField{Key: "run_id", Value: string(runID)}, LogField{Key: "sequence", Value: fmt.Sprint(sequence)},
		LogField{Key: "terminal_outcome", Value: string(TerminalInterrupted)})
	return true, nil
}

func reconcileProcessDecision(expected, observed ProcessIdentity, probeErr error) (string, TerminalOutcome) {
	if errors.Is(probeErr, ErrProcessNotFound) {
		return "owner_process_missing_after_grace", TerminalInterrupted
	}
	if probeErr != nil {
		return "owner_process_identity_uncertain_after_grace", TerminalCleanupUncertain
	}
	if expected.HostDigest == "" || expected.BootID == "" || expected.BirthToken == "" || observed.HostDigest == "" || observed.BootID == "" || observed.BirthToken == "" {
		return "owner_process_identity_incomplete_after_grace", TerminalCleanupUncertain
	}
	if expected.HostDigest != observed.HostDigest || expected.BootID != observed.BootID || expected.PID != observed.PID || expected.BirthToken != observed.BirthToken {
		return "owner_process_birth_mismatch_after_grace", TerminalInterrupted
	}
	return "exact_owner_process_still_live_but_lease_expired", ""
}

func (r *SQLiteRepository) markStalled(ctx context.Context, candidate reconciliationCandidate) error {
	result, err := r.db.ExecContext(ctx, `
UPDATE runs SET liveness = ?, updated_at = ?
WHERE run_id = ? AND current_attempt_id = ? AND terminal_outcome IS NULL`,
		string(LivenessStalled), formatTime(r.now()), string(candidate.runID), string(candidate.attemptID))
	if err != nil {
		return classifyStoreError("reconcile_stalled", "persist stalled owner state failed", err)
	}
	if changed, err := result.RowsAffected(); err != nil || changed != 1 {
		return runError(CodeStaleFence, "reconcile_stalled", candidate.runID, "owner changed during reconciliation", false, err)
	}
	return nil
}

func (r *SQLiteRepository) recordReconciliation(ctx context.Context, candidate reconciliationCandidate, action, decision string) error {
	evidenceClass := "safe_identity_only"
	if candidate.attemptID == "" {
		evidenceClass = "acceptance_timestamp_only"
	}
	evidence, _ := json.Marshal(map[string]string{"evidence": evidenceClass})
	var attempt any
	if candidate.attemptID != "" {
		attempt = string(candidate.attemptID)
	}
	_, err := r.db.ExecContext(ctx, `INSERT INTO reconciliation_log (run_id, attempt_id, observed_at, action, decision, evidence_json) VALUES (?, ?, ?, ?, ?, ?)`,
		string(candidate.runID), attempt, formatTime(r.now()), action, decision, string(evidence))
	if err != nil {
		return classifyStoreError("reconcile_log", "persist reconciliation evidence failed", err)
	}
	return nil
}

// ReconciliationEvidence returns newest-first safe reconciliation facts for a
// bounded support export. The stored evidence payload is deliberately reduced
// to its allowlisted classification rather than exposed as arbitrary JSON.
func (r *SQLiteRepository) ReconciliationEvidence(ctx context.Context, limit int) ([]ReconciliationEvidence, error) {
	if limit < 1 || limit > 200 {
		return nil, invalidField("reconciliation_evidence.limit", "must be between 1 and 200")
	}
	rows, err := r.db.QueryContext(ctx, `
SELECT run_id, attempt_id, observed_at, action, decision, evidence_json
FROM reconciliation_log ORDER BY observed_at DESC, id DESC LIMIT ?`, limit)
	if err != nil {
		return nil, classifyStoreError("reconciliation_evidence", "read reconciliation evidence failed", err)
	}
	defer rows.Close()
	result := make([]ReconciliationEvidence, 0, limit)
	for rows.Next() {
		var item ReconciliationEvidence
		var attempt sql.NullString
		var observed, encodedEvidence string
		if err := rows.Scan(&item.RunID, &attempt, &observed, &item.Action, &item.Decision, &encodedEvidence); err != nil {
			return nil, classifyStoreError("reconciliation_evidence", "decode reconciliation evidence failed", err)
		}
		item.AttemptID = AttemptID(attempt.String)
		item.ObservedAt, err = parseTime(observed)
		if err != nil {
			return nil, err
		}
		var stored map[string]string
		if json.Unmarshal([]byte(encodedEvidence), &stored) == nil {
			switch stored["evidence"] {
			case "safe_identity_only", "acceptance_timestamp_only":
				item.Evidence = stored["evidence"]
			}
		}
		if item.Evidence == "" {
			item.Evidence = "omitted"
		}
		result = append(result, item)
	}
	if err := rows.Err(); err != nil {
		return nil, classifyStoreError("reconciliation_evidence", "read reconciliation evidence failed", err)
	}
	return result, nil
}

